import{d as D,C as p,o as N,c as E,a3 as i,E as a,j as t,a as e}from"./chunks/framework.Q4yG9rk_.js";const B=JSON.parse('{"title":"庄子·知北游","description":"从知的三次问道，到天地之美、啮缺睡寐与天地之委形，理解认知、言说、无为和占有之间的关系。","frontmatter":{"title":"庄子·知北游","description":"从知的三次问道，到天地之美、啮缺睡寐与天地之委形，理解认知、言说、无为和占有之间的关系。","category":"guide","aliases":["知北游","庄子知北游","zhuangzi chapter 22"],"source":["《庄子》"]},"headers":[],"relativePath":"daoism/zhuang-zi/chapter-22.md","filePath":"daoism/zhuang-zi/chapter-22.md","lastUpdated":1792641266000}'),R={name:"daoism/zhuang-zi/chapter-22.md"},H=D({...R,setup(G){const o=[{id:"zby_inquiry_s1",label:"知问无为谓：知道、安道、得道",sentences:[[{text:"知",glossary:"zby_inquiry_zhi"},"北游于玄水之上，登",{text:"隐弅",glossary:"zby_inquiry_yinfen"},"之丘，而适遭",{text:"无为谓",glossary:"zby_inquiry_wuweiwei"},"焉。"],["知谓无为谓曰：「予欲有问乎若：",{text:"何思何虑则知道",glossary:"zby_inquiry_silu"},"？",{text:"何处何服则安道",glossary:"zby_inquiry_chufu"},"？",{text:"何从何道则得道",glossary:"zby_inquiry_congdao"},"？」"],["三问而无为谓不答也。非不答，不知答也。"]]},{id:"zby_inquiry_s2",label:"知问狂屈：欲言而忘",sentences:[["知不得问，反于白水之南，登狐阕之上，而睹狂屈焉。知以之言也问乎狂屈。"],["狂屈曰：「唉！予知之，将语若。」",{text:"中欲言而忘其所欲言",glossary:"zby_inquiry_wangyan"},"。"]]},{id:"zby_inquiry_s3",label:"知问黄帝：无思无虑、无处无服、无从无道",sentences:[["知不得问，反于帝宫，见黄帝而问焉。"],["黄帝曰：「无思无虑始知道，无处无服始安道，无从无道始得道。」"],["知问黄帝曰：「我与若知之，彼与彼不知也，其孰是邪？」"],["黄帝曰：「彼无为谓真是也，狂屈似之，我与汝终不近也。"]]},{id:"zby_inquiry_s4",label:"不言之教：道、德、仁、义、礼",sentences:[["夫",{text:"知者不言，言者不知",glossary:"zby_inquiry_buyan"},"，故圣人行不言之教。",{text:"道不可致，德不可至",glossary:"zby_inquiry_zhide"},"。仁可为也，义可亏也，礼相伪也。"],["故曰：『失道而后德，失德而后仁，失仁而后义，失义而后礼。』"],["礼者，",{text:"道之华",glossary:"zby_inquiry_lihua"},"而乱之首也。"]]},{id:"zby_inquiry_s5",label:"为道日损：无为与复归根",sentences:[["故曰：『",{text:"为道者日损",glossary:"zby_inquiry_risun"},"，损之又损之，以至于无为。",{text:"无为而无不为",glossary:"zby_inquiry_wuwei"},"也。』"],[{text:"今已为物也",glossary:"zby_inquiry_weiwu"},"，欲复归根，不亦难乎！其易也其唯大人乎！"]]},{id:"zby_inquiry_s6",label:"死生为徒：气之聚散",sentences:[["生也死之徒，死也生之始，孰知其纪！"],["人之生，",{text:"气之聚",glossary:"zby_inquiry_qiju"},"也。聚则为生，散则为死。若",{text:"死生为徒",glossary:"zby_inquiry_situ"},"，吾又何患！故万物一也。"]]},{id:"zby_inquiry_s7",label:"神奇与臭腐：通天下一气耳",sentences:[["是其所美者为神奇，其所恶者为",{text:"臭腐",glossary:"zby_inquiry_choufu"},"。臭腐复化为神奇，神奇复化为臭腐。"],["故曰：『通天下一气耳。』",{text:"圣人故贵一",glossary:"zby_inquiry_guiyi"},"。」"]]},{id:"zby_inquiry_s8",label:"再问为何不近：不知、忘之、知之",sentences:[["知谓黄帝曰：「吾问无为谓，无为谓不应我，非不我应，不知应我也；"],["吾问狂屈，狂屈中欲告我而不我告，非不我告，中欲告而忘之也；"],["今予问乎若，若知之，奚故不近？」"],["黄帝曰：「彼其真是也，以其不知也；此其似之也，以其忘之也；予与若终不近也，以其知之也。」"],["狂屈闻之，以黄帝为知言。"]]}],y=[{id:"zby_inquiry_zhi",term:"知",pinyin:"zhī / zhì",meaning:"寓言人物，以知命名，关联智识、认知。传统亦有读作智者；项目可依采用的注本统一读音。不是普通人的完整传记。"},{id:"zby_inquiry_yinfen",term:"隐弅",pinyin:"yǐn fèn",meaning:"篇中的丘名。玄水、白水、狐阕等共同构成寓言游历的空间，不在此坐实地理位置。"},{id:"zby_inquiry_wuweiwei",term:"无为谓",pinyin:"wú wéi wèi",meaning:"寓言人物名，可联系无为、无言说理解。不知答是原文特别指出的状态，不直接等于拒绝交流或故意摆出高人姿态。"},{id:"zby_inquiry_silu",term:"何思何虑则知道",pinyin:"hé sī hé lǜ zé zhī dào",meaning:"要怎样思考，才能知道道？知道在此应拆开理解为知其道，不只用现代知道一词解释。"},{id:"zby_inquiry_chufu",term:"何处何服则安道",pinyin:"hé chǔ hé fú zé ān dào",meaning:"怎样处身、服行，才能安于道？服的具体训释有空间，不只指服装，也不强定为某套修炼方法。"},{id:"zby_inquiry_congdao",term:"何从何道则得道",pinyin:"hé cóng hé dǎo zé dé dào",meaning:"从循什么、沿何道路才能得道？前一道有道路、导行等解释，后一道指所求之道，读音宜依注本统一。"},{id:"zby_inquiry_wangyan",term:"中欲言而忘其所欲言",pinyin:"zhōng yù yán ér wàng qí suǒ yù yán",meaning:"正欲说、心中欲说时，却忘了要说的内容。中有具体训释空间，不必补成狂屈有意选择忘言。"},{id:"zby_inquiry_buyan",term:"知者不言，言者不知",pinyin:"zhī zhě bù yán, yán zhě bù zhī",meaning:"以强烈对举指出对道的通达与固定言说之间的距离。与《老子》同句相通，不等于知者不博的改写，也不直接否定一切表达。"},{id:"zby_inquiry_zhide",term:"道不可致，德不可至",pinyin:"dào bù kě zhì, dé bù kě zhì",meaning:"道、德不能像外在对象一样被招致、达到。致、至的训释有空间，可先联系不能强求、不能据有理解。"},{id:"zby_inquiry_lihua",term:"道之华",pinyin:"dào zhī huá",meaning:"道的外在文饰、浮华。礼相伪与乱之首构成对失根后仪节的尖锐批评，不应弱化成原文完全肯定礼制。"},{id:"zby_inquiry_risun",term:"为道者日损",pinyin:"wéi dào zhě rì sǔn",meaning:"为道逐日减损。可联系减损强作、执持与自以为已知理解，不是要求损伤身体、减少必要营养或丢弃全部知识。"},{id:"zby_inquiry_wuwei",term:"无为而无不为",pinyin:"wú wéi ér wú bù wéi",meaning:"不强作而事物得其展开的理想表达。不是个人无所不能、任何任务都能成功的承诺。"},{id:"zby_inquiry_weiwu",term:"今已为物也",pinyin:"jīn yǐ wéi wù yě",meaning:"已经成为有形之物，亦可联系受物拘系理解。复归根：返归根本；不宜只译成积累了太多物质财产。"},{id:"zby_inquiry_situ",term:"死生为徒",pinyin:"sǐ shēng wéi tú",meaning:"死与生相伴、同属变化。徒：同伴、同类。纪：条理、纲纪。并不取消具体生命的死亡。"},{id:"zby_inquiry_qiju",term:"气之聚",pinyin:"qì zhī jù",meaning:"以气的聚散说明生死。属于古代生成论语境，不直接等同现代物理能量，也不证明个人记忆与意识永存。"},{id:"zby_inquiry_choufu",term:"臭腐",pinyin:"chòu fǔ",meaning:"腐臭之物，与人所美的神奇相对。相互转化说明价值判断所指的状态并非永久固定。"},{id:"zby_inquiry_guiyi",term:"圣人故贵一",pinyin:"shèng rén gù guì yī",meaning:"重视贯通变化的整体、相通之根本。不是要求万物抹去差异，也不宜直接解释成政治意见必须统一。"}],l=[{id:"zby_heaven_s1",label:"天地、四时、万物：有而不言",sentences:[[{text:"天地有大美而不言",glossary:"zby_heaven_damei"},"，四时有明法而不议，万物有",{text:"成理",glossary:"zby_heaven_chengli"},"而不说。"],["圣人者，",{text:"原天地之美",glossary:"zby_heaven_yuan"},"而达万物之理。"],["是故至人无为，",{text:"大圣不作",glossary:"zby_heaven_buzuo"},"，观于天地之谓也。"]]},{id:"zby_heaven_s2",label:"百化与本根：死生方圆",sentences:[["今彼",{text:"神明至精，与彼百化",glossary:"zby_heaven_baihua"},"。物已死生方圆，莫知其根也。"],[{text:"扁然而万物",glossary:"zby_heaven_pianran"},"，自古以固存。"]]},{id:"zby_heaven_s3",label:"六合与秋豪：大小皆有所待",sentences:[[{text:"六合",glossary:"zby_heaven_liuhe"},"为巨，未离其内；秋豪为小，待之成体；"],["天下莫不沈浮，",{text:"终身不故",glossary:"zby_heaven_bugu"},"；阴阳四时运行，各得其序；"]]},{id:"zby_heaven_s4",label:"若亡而存，不形而神：此之谓本根",sentences:[[{text:"惛然若亡而存",glossary:"zby_heaven_hunran"},"；油然不形而神；",{text:"万物畜而不知",glossary:"zby_heaven_xu"},"："],["此之谓",{text:"本根",glossary:"zby_heaven_bengen"},"，可以观于天矣！"]]}],g=[{id:"zby_heaven_damei",term:"天地有大美而不言",pinyin:"tiān dì yǒu dà měi ér bù yán",meaning:"天地的广大生成与秩序不借语言自陈。不是说天地具有人的知识而刻意保密。"},{id:"zby_heaven_chengli",term:"成理",pinyin:"chéng lǐ",meaning:"万物形成、运行所具的条理。不只指已完成的理论，也不把所有现状认成伦理上应当如此。"},{id:"zby_heaven_yuan",term:"原天地之美",pinyin:"yuán tiān dì zhī měi",meaning:"推原、探究或本于天地之美。与达万物之理相接，说明本段仍保留观察、理解与通达。"},{id:"zby_heaven_buzuo",term:"大圣不作",pinyin:"dà shèng bù zuò",meaning:"不妄兴、不强作。与观于天地相接，不等于停止全部行动。"},{id:"zby_heaven_baihua",term:"神明至精，与彼百化",pinyin:"shén míng zhì jīng, yǔ bǐ bǎi huà",meaning:"以神妙精微描写根本与万物变化相通。彼的所指与句读有讨论空间，不强定为某个人的精神控制百化。"},{id:"zby_heaven_pianran",term:"扁然而万物",pinyin:"piān rán ér wàn wù",meaning:"疑难句，扁然有遍然、广大等解释。结合下文，把握万物与本根相通，不强定单一字义。"},{id:"zby_heaven_liuhe",term:"六合",pinyin:"liù hé",meaning:"上下四方，借指广大的空间。秋豪通秋毫，指极细之物。大小都不是脱离根本而独立生成。"},{id:"zby_heaven_bugu",term:"终身不故",pinyin:"zhōng shēn bù gù",meaning:"始终不保持旧状、不断变化等。故联系旧理解，不宜只释为停止。沈浮：沉浮、变化起伏。"},{id:"zby_heaven_hunran",term:"惛然若亡而存",pinyin:"hūn rán ruò wú ér cún",meaning:"幽昧难辨，仿佛没有却有所存。亡在此可联系无理解，读音可依底本统一。不是某个已确定对象死亡后又复活。"},{id:"zby_heaven_xu",term:"万物畜而不知",pinyin:"wàn wù xù ér bù zhī",meaning:"万物得到养育而不知其所以然，亦有联系养育不自知者。主语关系有解释空间，不直接定为道没有自我意识。"},{id:"zby_heaven_bengen",term:"本根",pinyin:"běn gēn",meaning:"生成与变化所依的根本，可联系道理解。不是可以直接指认的某件物体。观于天保留观察、体认与取法的方向。"}];l[0].sentences=[[{text:"天地有大美而不言",glossary:"zby_heaven_damei"},"，四时有明法而不议，万物有",{text:"成理",glossary:"zby_heaven_chengli"},"而不说。"],["圣人者，",{text:"原天地之美",glossary:"zby_heaven_yuan"},"而达万物之理。"],["是故至人无为，",{text:"大圣不作",glossary:"zby_heaven_buzuo"},"，观于天地之谓也。"]],l[1].sentences=[[{text:"神明至精，与彼百化",glossary:"zby_heaven_baihua"},"。物已死生方圆，莫知其根也。"],[{text:"扁然而万物",glossary:"zby_heaven_pianran"},"，自古以固存。"]],l[2].sentences=[[{text:"六合",glossary:"zby_heaven_liuhe"},"为巨，未离其内；秋豪为小，待之成体；"],["天下莫不沈浮，",{text:"终身不故",glossary:"zby_heaven_bugu"},"；阴阳四时运行，各得其序；"]],l[3].sentences=[[{text:"惛然若亡而存",glossary:"zby_heaven_hunran"},"；油然不形而神；",{text:"万物畜而不知",glossary:"zby_heaven_xu"},"："],["此之谓",{text:"本根",glossary:"zby_heaven_bengen"},"，可以观于天矣！"]];const h=[{id:"zby_nie_s1",label:"正形一视：天和将至",sentences:[[{text:"啮缺",glossary:"zby_nie_que"},"问道乎",{text:"被衣",glossary:"zby_nie_piyi"},"，被衣曰：「若正汝形，一汝视，天和将至；"],[{text:"摄汝知，一汝度",glossary:"zby_nie_shezhi"},"，神将来舍。"],["德将为汝美，道将为汝居。汝",{text:"瞳焉如新生之犊",glossary:"zby_nie_tong"},"而无求其故。」"]]},{id:"zby_nie_s2",label:"言未卒而睡：被衣大说",sentences:[[{text:"言未卒，啮缺睡寐",glossary:"zby_nie_shui"},"。被衣大说，行歌而去之，曰："]]},{id:"zby_nie_s3",label:"槁骸死灰：不以故自持",sentences:[["「形若槁骸，心若死灰，",{text:"真其实知",glossary:"zby_nie_shizhi"},"，",{text:"不以故自持",glossary:"zby_nie_g u"},"。"],[{text:"媒媒晦晦",glossary:"zby_nie_meimei"},"，无心而不可与谋。彼何人哉！」"]]}],b=[{id:"zby_nie_que",term:"啮缺",pinyin:"niè quē",meaning:"《庄子》中的问道人物，本篇向被衣问道。具体历史身世不详，按本段人物关系阅读。"},{id:"zby_nie_piyi",term:"被衣",pinyin:"pī yī",meaning:"《庄子》中的得道人物，本篇被啮缺问道。被衣的读音可依注本统一。"},{id:"zby_nie_shezhi",term:"摄汝知，一汝度",pinyin:"shè rǔ zhī, yī rǔ dù",meaning:"收摄智识，使心度、度量专一。不是取消全部判断；正形一视与摄知一度共同说明不分散、不强逐的状态。"},{id:"zby_nie_tong",term:"瞳焉如新生之犊",pinyin:"tóng yān rú xīn shēng zhī dú",meaning:"如初生小牛般无知、朴直或目光安然，瞳焉的训释有差异。不只按现代眼睛清澈解。犊：小牛。"},{id:"zby_nie_shui",term:"言未卒，啮缺睡寐",pinyin:"yán wèi zú, niè quē shuì mèi",meaning:"话未说完，啮缺已经入睡。被衣大说的说通悦，读 yuè。是寓言反转，不证明课堂入睡就是得道。"},{id:"zby_nie_shizhi",term:"真其实知",pinyin:"zhēn qí shí zhī",meaning:"疑难词组，有真知实存、知真实而不造作等解释。结合心若死灰，不能把它直接改成完全没有认识能力。"},{id:"zby_nie_g u",term:"不以故自持",pinyin:"bù yǐ gù zì chí",meaning:"不以旧见、成故或机故固持自身。故有不同解释，不等于过去的一切经验都应丢弃。"},{id:"zby_nie_meimei",term:"媒媒晦晦",pinyin:"méi méi huì huì",meaning:"幽昧、不显智巧的样子，具体训释有空间。无心而不可与谋可联系无机心、不参与机巧筹划理解。"}],_=[{id:"zby_entrust_s1",label:"道可得而有乎：由身反问",sentences:[["舜问乎",{text:"丞",glossary:"zby_entrust_cheng"},"：「",{text:"道可得而有乎",glossary:"zby_entrust_you"},"？」"],["曰：「汝身非汝有也，汝何得有夫道！」"],["舜曰：「吾身非吾有也，孰有之哉？」"]]},{id:"zby_entrust_s2",label:"委形、委和、委顺、委蜕",sentences:[["曰：「是天地之",{text:"委形",glossary:"zby_entrust_weixing"},"也；生非汝有，是天地之委和也；"],["性命非汝有，是天地之委顺也；子孙非汝有，是天地之",{text:"委蜕",glossary:"zby_entrust_weitui"},"也。"]]},{id:"zby_entrust_s3",label:"行、处、食：又胡可得而有",sentences:[["故",{text:"行不知所往，处不知所持，食不知所味",glossary:"zby_entrust_buzhi"},"。"],["天地之",{text:"强阳气",glossary:"zby_entrust_qiangyang"},"也，又胡可得而有邪！」"]]}],u=[{id:"zby_entrust_cheng",term:"丞",pinyin:"chéng",meaning:"舜的问答对象，传统有辅佐者、人物名等解释。不在此强定为某一历史人物。"},{id:"zby_entrust_you",term:"道可得而有乎",pinyin:"dào kě dé ér yǒu hū",meaning:"道能被获得、占有吗？有联系据为己有理解，与知道、安道的求问不同，直接触及占有方式。"},{id:"zby_entrust_weixing",term:"天地之委形",pinyin:"tiān dì zhī wěi xíng",meaning:"天地所委聚、所赋予的形体。委可联系委积、委付理解，不必拟人成有合同关系的委托方。委和、委顺分别联系生命之和与性命所循。"},{id:"zby_entrust_weitui",term:"天地之委蜕",pinyin:"tiān dì zhī wěi tuì",meaning:"天地变化、形体相续的表现。以蜕说明子孙属于生命变化，不是可以由父母绝对占有的财物。"},{id:"zby_entrust_buzhi",term:"行不知所往，处不知所持，食不知所味",pinyin:"xíng bù zhī suǒ wǎng, chǔ bù zhī suǒ chí, shí bù zhī suǒ wèi",meaning:"可联系不以自我筹计、固执或滋味分别拘系日常行动理解。整组句子有解释空间，不宜作为不辨方向、不管饮食安全的生活指令。"},{id:"zby_entrust_qiangyang",term:"强阳气",pinyin:"qiáng yáng qì",meaning:"运行、动荡或强健的气，具体训释有差异。不只等于阴阳学说中的阳气，也不直接把气与道当成完全同义词。"}],m=[{id:"zby_lao_s1",label:"问至道：疏瀹、澡雪与掊击",sentences:[["孔子问于老聃曰：「今日晏闲，敢问至道。」"],["老聃曰：「汝齐戒，",{text:"疏瀹而心",glossary:"zby_lao_shuyue"},"，澡雪而精神，",{text:"掊击而知",glossary:"zby_lao_pouji"},"。"],["夫道，窨然难言哉！将为汝言其",{text:"崖略",glossary:"zby_lao_yalue"},"："]]},{id:"zby_lao_s2",label:"昭昭生于冥冥：精神、精与形",sentences:[["夫",{text:"昭昭生于冥冥",glossary:"zby_lao_zhaozhao"},"，有伦生于无形，精神生于道，形本生于精，而万物以形相生。"],["故",{text:"九窍者胎生，八窍者卵生",glossary:"zby_lao_jiuqiao"},"。其来无迹，其往无崖，无门无房，四达之皇皇也。"]]},{id:"zby_lao_s3",label:"邀于此者：用心不劳，应物无方",sentences:[[{text:"邀于此者",glossary:"zby_lao_yao"},"，四肢强，思虑",{text:"恂达",glossary:"zby_lao_xunda"},"，耳目聪明。"],["其用心不劳，其应物无方，天不得不高，地不得不广，日月不得不行，万物不得不昌，此其道与！"]]},{id:"zby_lao_s4",label:"博辩与所保：益损不加，运量不匮",sentences:[["且夫博之不必知，辩之不必慧，圣人以断之矣！"],["若夫益之而不加益，损之而不加损者，圣人之所保也。"],["渊渊乎其若海，",{text:"魏魏",glossary:"zby_lao_weiwei"},"乎其终则复始也。运量万物而不匮。"],["则君子之道，彼其外与！万物皆往资焉而不匮。此其道与！"]]},{id:"zby_lao_s5",label:"直且为人：将反于宗",sentences:[[{text:"中国有人焉",glossary:"zby_lao_zhongguo"},"，非阴非阳，处于天地之间，直且为人，将反于宗。"],["自本观之，生者，",{text:"喑噫物",glossary:"zby_lao_yinyi"},"也。虽有寿夭，相去几何？须臾之说也，奚足以为尧、桀之是非！"]]},{id:"zby_lao_s6",label:"遭之不违，过之不守：调与偶",sentences:[[{text:"果蓏",glossary:"zby_lao_guoluo"},"有理，人伦虽难，所以相齿。"],["圣人遭之而不违，过之而不守。",{text:"调而应之",glossary:"zby_lao_tiao"},"，德也；",{text:"偶而应之",glossary:"zby_lao_ou"},"，道也。帝之所兴，王之所起也。"]]},{id:"zby_lao_s7",label:"白驹过隙：已化而生，又化而死",sentences:[["人生天地之间，若",{text:"白驹之过隙",glossary:"zby_lao_baiju"},"，忽然而已。"],["注然勃然，莫不出焉；油然寥然，莫不入焉。已化而生，又化而死。生物哀之，人类悲之。"],[{text:"解其天韬，堕其天帙",glossary:"zby_lao_tiantao"},"。纷乎宛乎，魂魄将往，乃身从之。乃",{text:"大归",glossary:"zby_lao_dagui"},"乎！"]]},{id:"zby_lao_s8",label:"论说与至道：此之谓大得",sentences:[["不形之形，形之不形，是人之所同知也，非将至之所务也，此众人之所同论也。"],["彼至则不论，论则不至；",{text:"明见无值",glossary:"zby_lao_wuzhi"},"，辩不若默；道不可闻，闻不若塞：",{text:"此之谓大得",glossary:"zby_lao_dade"},"。」"]]}],z=[{id:"zby_lao_shuyue",term:"疏瀹而心",pinyin:"shū yuè rǔ xīn",meaning:"疏通、洗涤你的心。而在此联系汝理解，下文而精神、而知同。齐戒通斋戒，澡雪指洗涤，整体写问道前的清理与收摄。"},{id:"zby_lao_pouji",term:"掊击而知",pinyin:"pǒu jī rǔ zhī",meaning:"击破、消解你所据执的智识。掊击是强烈譬喻，不是损伤大脑、取消判断或丢弃全部知识的指令。"},{id:"zby_lao_yalue",term:"崖略",pinyin:"yá lüè",meaning:"边际轮廓、大概。窨然常联系幽深理解，读音与字形宜依底本统一；言其崖略承认说明不能穷尽所述。"},{id:"zby_lao_zhaozhao",term:"昭昭生于冥冥",pinyin:"zhāo zhāo shēng yú míng míng",meaning:"明著者生于幽冥难见者。与有伦生于无形相接，指出可见形态与条理并不以同样可见的根本为前提。"},{id:"zby_lao_jiuqiao",term:"九窍者胎生，八窍者卵生",pinyin:"jiǔ qiào zhě tāi shēng, bā qiào zhě luǎn shēng",meaning:"古代以窍数区分胎生、卵生的生成论说，不直接等同现代动物分类，也不只限定为人与鸟。"},{id:"zby_lao_yao",term:"邀于此者",pinyin:"yāo yú cǐ zhě",meaning:"与此遇合、会合者。联系与道相通理解，不是邀请道进入身体的具体仪式。"},{id:"zby_lao_xunda",term:"恂达",pinyin:"xún dá",meaning:"顺畅通达等，具体训释有空间。用心不劳、应物无方强调不强作、不固守一法，不保证毫无疲劳。"},{id:"zby_lao_weiwei",term:"魏魏",pinyin:"wēi wēi",meaning:"高大、巍然的样子。运量联系运行、涵运理解；匮：不足、穷乏。"},{id:"zby_lao_zhongguo",term:"中国有人焉",pinyin:"zhōng guó yǒu rén yān",meaning:"中国的具体所指有不同解释，可联系中土、天地之间的生活领域阅读；不直接等同现代国家名称。非阴非阳也不宜改成某人获得超越阴阳的特殊能力。"},{id:"zby_lao_yinyi",term:"喑噫物",pinyin:"yīn yī wù",meaning:"气息、气化所成之物等，喑噫的读音和训释有讨论空间。自本观之限定其观察尺度，不直接贬低个体生命。"},{id:"zby_lao_guoluo",term:"果蓏",pinyin:"guǒ luǒ",meaning:"木本、草本所结果实等，古代分类有不同说法。相齿联系相次、排列理解，借果实之理说明复杂人伦亦有可应接的条理。"},{id:"zby_lao_tiao",term:"调而应之",pinyin:"tiáo ér yìng zhī",meaning:"调和、相合而回应。本篇与偶而应之并列，分别联系德与道理解。"},{id:"zby_lao_ou",term:"偶而应之",pinyin:"ǒu ér yìng zhī",meaning:"偶可联系相配、遇合理解。不必分成有意识与无意识，也不据此建立德比道低一级的固定阶梯。"},{id:"zby_lao_baiju",term:"白驹之过隙",pinyin:"bái jū zhī guò xì",meaning:"白马疾驰经过狭隙般短暂，亦有联系日影者。重点在迅疾流逝，不必补成白马最快、缝隙最窄。"},{id:"zby_lao_tiantao",term:"解其天韬，堕其天帙",pinyin:"jiě qí tiān tāo, huī qí tiān zhì",meaning:"解开天然的包裹，脱落天然的束缚。韬、帙借囊套、书衣等作譬喻；堕有依毁、脱落义读 huī 者，宜依注本统一。"},{id:"zby_lao_dagui",term:"大归",pinyin:"dà guī",meaning:"生命归入变化根本的强烈表达。不是个人意识永存的证明，也不等于死亡没有实际终结与哀伤。"},{id:"zby_lao_wuzhi",term:"明见无值",pinyin:"míng jiàn wú zhí",meaning:"疑难词组，有明见而无所对待、无可当值等解释。不直接等同无法用语言表达，整体应与辩不若默连读。"},{id:"zby_lao_dade",term:"此之谓大得",pinyin:"cǐ zhī wèi dà dé",meaning:"称为大的通达、所得。塞在闻不若塞中指闭塞闻受，按此义读 sè；不能作为损伤感官或拒绝所有信息的建议。"}],c=[{id:"zby_every_s1",label:"所谓道，恶乎在：无所不在",sentences:[[{text:"东郭子",glossary:"zby_every_people"},"问于庄子曰：「所谓道，恶乎在？」庄子曰：「无所不在。」"],["东郭子曰：「",{text:"期而后可",glossary:"zby_every_qi"},"。」"]]},{id:"zby_every_s2",label:"蝼蚁、稊稗、瓦甓、屎溺",sentences:[["庄子曰：「在蝼蚁。」曰：「何其下邪？」"],["曰：「在",{text:"稊稗",glossary:"zby_every_tibai"},"。」曰：「何其愈下邪？」"],["曰：「在",{text:"瓦甓",glossary:"zby_every_wapi"},"。」曰：「何其愈甚邪？」"],["曰：「在",{text:"屎溺",glossary:"zby_every_shiniao"},"。」东郭子不应。"]]},{id:"zby_every_s3",label:"履狶之喻：每下愈况，汝唯莫必",sentences:[["庄子曰：「夫子之问也，固不及质。正、获之问于监市",{text:"履狶",glossary:"zby_every_lvxi"},"也，『",{text:"每下愈况",glossary:"zby_every_kuang"},"』。"],[{text:"汝唯莫必",glossary:"zby_every_mobi"},"，无乎逃物。至道若是，大言亦然。"],[{text:"周遍咸三者",glossary:"zby_every_zhou"},"，异名同实，其指一也。"]]},{id:"zby_every_s4",label:"游乎无有之宫：同合而论",sentences:[[{text:"尝相与游乎无有之宫",glossary:"zby_every_chang"},"，同合而论，无所终穷乎！"],["尝相与无为乎！澹澹而静乎！漠而清乎！调而闲乎！"],["寥已吾志，",{text:"无往焉而不知其所至",glossary:"zby_every_wuwang"},"，去而来不知其所止。"]]},{id:"zby_every_s5",label:"大知入焉：不知其所穷",sentences:[["吾往来焉而不知其所终，彷徨乎",{text:"冯闳",glossary:"zby_every_fenghong"},"，大知入焉而不知其所穷。"]]},{id:"zby_every_s6",label:"物物者与物：际与不际",sentences:[[{text:"物物者",glossary:"zby_every_wuwu"},"与物无际，而物有际者，所谓物际者也。"],["不际之际，际之不际者也。"]]},{id:"zby_every_s7",label:"为盈虚而非盈虚：本末与积散",sentences:[["谓",{text:"盈虚衰杀",glossary:"zby_every_shuai"},"，",{text:"彼为盈虚非盈虚",glossary:"zby_every_weifei"},"，彼为衰杀非衰杀，彼为本末非本末，彼为积散非积散也。」"]]}],x=[{id:"zby_every_people",term:"东郭子",pinyin:"dōng guō zǐ",meaning:"篇中向庄子问道的人物。具体身份不详，不未经辨析便与《田子方》的东郭顺子合为一人。恶乎在的恶读 wū，意为在哪里。"},{id:"zby_every_qi",term:"期而后可",pinyin:"qī ér hòu kě",meaning:"指定、限定一个所在才可以。期在此联系指定理解，显示问者希望得到具体位置。"},{id:"zby_every_tibai",term:"稊稗",pinyin:"tí bài",meaning:"杂草、似禾之草。蝼蚁、稊稗、瓦甓、屎溺的次序，依问者所认的高下而逐步降低。"},{id:"zby_every_wapi",term:"瓦甓",pinyin:"wǎ pì",meaning:"瓦与砖。甓：砖。不只在有生命之物中说道，也在器物中说道。"},{id:"zby_every_shiniao",term:"屎溺",pinyin:"shǐ niào",meaning:"粪便与尿。溺在尿义通常读 niào，亦可依注本处理古读。回答打破高贵洁净才有道的预设，不取消卫生区别。"},{id:"zby_every_lvxi",term:"履狶",pinyin:"lǚ xī",meaning:"踩按猪体以察肥瘦。正、获及监市的身份、句读有讨论空间，不强定为两位屠夫踩猪蹄。狶：猪。"},{id:"zby_every_kuang",term:"每下愈况",pinyin:"měi xià yù kuàng",meaning:"越向下察验，越能看清情况。况联系显明、比较察知理解；原文为每下愈况，不宜直接替换成后来常用的每况愈下。"},{id:"zby_every_mobi",term:"汝唯莫必",pinyin:"rǔ wéi mò bì",meaning:"不要坚持道只能在某一处、某一类物中。无乎逃物联系无物不在其内理解，不是鼓励不作任何确定判断。"},{id:"zby_every_zhou",term:"周遍咸三者",pinyin:"zhōu biàn xián sān zhě",meaning:"周、遍、咸三个说法，都指普遍、全体。异名同实限定于这里的三个词，不是所有不同概念都完全同义。"},{id:"zby_every_chang",term:"尝相与游乎无有之宫",pinyin:"cháng xiāng yǔ yóu hū wú yǒu zhī gōng",meaning:"试与我一同游于无有之宫。尝在此联系尝试、姑且理解，不必译成两人曾经共同经历。无有之宫是譬喻境域，非实际建筑。"},{id:"zby_every_wuwang",term:"无往焉而不知其所至",pinyin:"wú wǎng yān ér bù zhī qí suǒ zhì",meaning:"依现有句式，可理解为没有所往而不知所至，含双重否定。字句与前后衔接有讨论空间，不能删去前一否定，直接译成到哪里都不知道。"},{id:"zby_every_fenghong",term:"冯闳",pinyin:"féng hóng",meaning:"广大、空旷的境域或状态，具体训释与音读有差异。大知虽入其中，仍不能穷尽。"},{id:"zby_every_wuwu",term:"物物者",pinyin:"wù wù zhě",meaning:"使物成为物、生成事物的根本，可联系道理解。不同于把个人解释成绝对驾驭万物的主体。际：边际、界限或相接。"},{id:"zby_every_shuai",term:"盈虚衰杀",pinyin:"yíng xū shuāi shài",meaning:"充盈、虚缺、衰退、减杀。杀在减杀义常读 shài，不作杀害解。"},{id:"zby_every_weifei",term:"彼为盈虚非盈虚",pinyin:"bǐ wéi yíng xū fēi yíng xū",meaning:"使盈虚发生、形成盈虚者，并不就是某一次盈虚。为的解释有空间，不能只译成道外表呈现为盈虚。下文衰杀、本末、积散同。"}],q=[{id:"zby_long_s1",label:"神农昼瞑：妸荷甘告老龙之死",sentences:[[{text:"妸荷甘",glossary:"zby_long_ehegan"},"与神农同学于老龙吉。神农",{text:"隐几，阖户昼瞑",glossary:"zby_long_yinji"},"。"],["妸荷甘日中",{text:"奓户",glossary:"zby_long_zhahu"},"而入，曰：「老龙死矣！」"]]},{id:"zby_long_s2",label:"神农放杖而笑：僻陋谩诞与狂言",sentences:[["神农隐几拥杖而起，嚗然放杖而笑，曰：「天知予",{text:"僻陋谩诞",glossary:"zby_long_mandan"},"，故弃予而死。"],["已矣，夫子",{text:"无所发予之狂言",glossary:"zby_long_kuangyan"},"而死矣夫！」"]]},{id:"zby_long_s3",label:"弇堈吊之论：体道者与藏言",sentences:[[{text:"弇堈吊",glossary:"zby_long_yangang"},"闻之，曰：「夫体道者，天下之君子所系焉。"],["今于道，",{text:"秋豪之端万分未得处一",glossary:"zby_long_weide"},"焉，而犹知藏其狂言而死，又况夫体道者乎！"]]},{id:"zby_long_s4",label:"视之无形，听之无声：所以论道而非道",sentences:[["视之无形，听之无声，于人之论者，谓之冥冥，",{text:"所以论道而非道",glossary:"zby_long_feidao"},"也。」"]]}],w=[{id:"zby_long_ehegan",term:"妸荷甘",pinyin:"ē hé gān",meaning:"篇中与神农同学的人物，姓名有异文、异读。老龙吉为二人之师，按寓言关系阅读，不在此坐实历史师承。"},{id:"zby_long_yinji",term:"隐几，阖户昼瞑",pinyin:"yǐn jī, hé hù zhòu míng",meaning:"倚靠几案，关门日间休息或睡眠。隐联系凭倚理解；几读 jī。"},{id:"zby_long_zhahu",term:"奓户",pinyin:"zhà hù",meaning:"打开、推开门户，奓的音义有讨论空间。嚗然常联系突然、放杖有声等理解。"},{id:"zby_long_mandan",term:"僻陋谩诞",pinyin:"pì lòu màn dàn",meaning:"鄙陋、漫诞等，自述中含自嘲、感叹意味。不能因为神农发笑就认定他没有失师之感。"},{id:"zby_long_kuangyan",term:"无所发予之狂言",pinyin:"wú suǒ fā yǔ zhī kuáng yán",meaning:"疑难句，发有启发、发明、发露等解释，予之狂言的归属关系也有讨论空间。不直接定为老师未及传授一种接近道的特殊狂言。"},{id:"zby_long_yangang",term:"弇堈吊",pinyin:"yǎn gāng diào",meaning:"篇中评论者的姓名，字形与读音可依底本统一。体道：体认、体现道；所系：所归依、所关注。"},{id:"zby_long_weide",term:"秋豪之端万分未得处一",pinyin:"qiū háo zhī duān wàn fēn wèi dé chǔ yī",meaning:"连秋毫末端的万分之一也未占得，极言距离道尚远。句中人物指向宜结合上下文，不能从夸张中计算实际掌握比例。"},{id:"zby_long_feidao",term:"所以论道而非道",pinyin:"suǒ yǐ lùn dào ér fēi dào",meaning:"用来论说道的，并不是道本身。区分言说与所论，不等于论说毫无帮助或必然造成伤害。"}],f=[{id:"zby_tai_s1",label:"无穷不知，无为知道",sentences:[["于是",{text:"泰清",glossary:"zby_tai_taiqing"},"问乎",{text:"无穷",glossary:"zby_tai_wuqiong"},"，曰：「子知道乎？」无穷曰：「吾不知。」"],["又问乎",{text:"无为",glossary:"zby_tai_wuwei"},"，无为曰：「吾知道。」"],["曰：「子之知道，",{text:"亦有数乎",glossary:"zby_tai_shu"},"？」曰：「有。」曰：「其数若何？」"]]},{id:"zby_tai_s2",label:"知道之数：贵、贱、约、散",sentences:[["无为曰：「吾知道之",{text:"可以贵、可以贱、可以约、可以散",glossary:"zby_tai_yuesan"},"，此吾所以知道之数也。」"]]},{id:"zby_tai_s3",label:"无始之判：不知深，知之浅",sentences:[["泰清以之言也问乎",{text:"无始",glossary:"zby_tai_wushi"},"，曰：「若是，则无穷之弗知与无为之知，孰是而孰非乎？」"],["无始曰：「",{text:"不知深矣，知之浅矣",glossary:"zby_tai_shenqian"},"；弗知内矣，知之外矣。」"],["于是泰清仰而叹曰：「弗知乃知乎，知乃不知乎！",{text:"孰知不知之知",glossary:"zby_tai_buzhi"},"？」"]]},{id:"zby_tai_s4",label:"闻、见、言皆非：道不当名",sentences:[["无始曰：「道不可闻，",{text:"闻而非也",glossary:"zby_tai_wenfei"},"；道不可见，见而非也；道不可言，言而非也！"],["知",{text:"形形之不形",glossary:"zby_tai_xingxing"},"乎！",{text:"道不当名",glossary:"zby_tai_dangming"},"。」"]]},{id:"zby_tai_s5",label:"问与应的限度：道无问，问无应",sentences:[["无始曰：「有问道而应之者，不知道也；虽问道者，亦未闻道。"],["道无问，问无应。无问问之，是问穷也；",{text:"无应应之，是无内也",glossary:"zby_tai_wunei"},"。"]]},{id:"zby_tai_s6",label:"宇宙与大初：不游乎太虚",sentences:[["以无内待问穷，若是者，外不观乎宇宙，内不知乎",{text:"大初",glossary:"zby_tai_dachu"},"。"],["是以不过乎",{text:"昆仑",glossary:"zby_tai_kunlun"},"，不游乎",{text:"太虚",glossary:"zby_tai_taixu2"},"。」"]]}],k=[{id:"zby_tai_taiqing",term:"泰清",pinyin:"tài qīng",meaning:"寓言人物名，本篇依次向无穷、无为、无始问道。名字参与问道情境，不能只按字面预定其境界。"},{id:"zby_tai_wuqiong",term:"无穷",pinyin:"wú qióng",meaning:"寓言人物名，答泰清「吾不知」。名字参与问道情境，不按字面预定境界高低。"},{id:"zby_tai_wuwei",term:"无为",pinyin:"wú wéi",meaning:"寓言人物名，本篇答「吾知道」，随后为无始评为知之浅，可见名字不预定境界。"},{id:"zby_tai_wushi",term:"无始",pinyin:"wú shǐ",meaning:"寓言人物名，本篇为泰清评断无穷之弗知与无为之知。名字参与问道情境，不按字面预定境界。"},{id:"zby_tai_shu",term:"亦有数乎",pinyin:"yì yǒu shù hū",meaning:"所知道的道是否有可列举的条目、方法或条理？数的范围不只指客观规律。"},{id:"zby_tai_yuesan",term:"可以贵、可以贱、可以约、可以散",pinyin:"kě yǐ guì, kě yǐ jiàn, kě yǐ yuē, kě yǐ sàn",meaning:"贵贱、收约与散开等不同运用或状态。具体主语关系有解释空间，不能据此把道限定为四种属性。"},{id:"zby_tai_shenqian",term:"不知深矣，知之浅矣",pinyin:"bù zhī shēn yǐ, zhī zhī qiǎn yǐ",meaning:"以反常评价区分不据知的通达与可条目化的知道。深浅、内外是譬喻，不是道内部与外部的地理分区。"},{id:"zby_tai_buzhi",term:"孰知不知之知",pinyin:"shú zhī bù zhī zhī zhī",meaning:"谁能理解不知这一种知？追问对认识的反省，不必宣布这是逻辑上绝无答案的问题。"},{id:"zby_tai_wenfei",term:"闻而非也",pinyin:"wén ér fēi yě",meaning:"所听不足以当作道本身；本篇与见而非也、言而非也并列，谓所见、所言同样不足为道。不是说感官接触一发生，道就从世界消失。"},{id:"zby_tai_xingxing",term:"形形之不形",pinyin:"xíng xíng zhī bù xíng",meaning:"使有形者成形的根本，自身不具有同样的固定形态。前一形有动词作用，与第六段物物者相通。"},{id:"zby_tai_dangming",term:"道不当名",pinyin:"dào bù dàng míng",meaning:"道不与某个名称完全相当，不能由定名穷尽。当联系相当、相称理解，不只译成道不应该有名字。"},{id:"zby_tai_wunei",term:"无应应之，是无内也",pinyin:"wú yìng yìng zhī, shì wú nèi yě",meaning:"对不能以确定答案应答的强作应答，缺乏真实内容、根本等。内的具体训释有空间，不等于这个人没有内心。"},{id:"zby_tai_dachu",term:"大初",pinyin:"tài chū",meaning:"太初、生成之初，大常联系太读。宇宙在古代涉及空间与时间，不直接等同现代天文学术语。"},{id:"zby_tai_kunlun",term:"昆仑",pinyin:"kūn lún",meaning:"神话中的山岳名，本篇与太虚并列，借以描写通达、游行的境域。不是要求肉身登越某座山才算得道。"},{id:"zby_tai_taixu2",term:"太虚",pinyin:"tài xū",meaning:"广大的虚空境域，本篇与昆仑并列，描写通达、游行的境域，非要求肉身抵达某处。"}],P=[{id:"zby_light_s1",label:"光曜问无有：有乎，无有乎",sentences:[[{text:"光曜",glossary:"zby_light_guangyao"},"问乎",{text:"无有",glossary:"zby_light_wuyou"},"曰：「夫子有乎？其无有乎？」"],["光曜不得问而",{text:"孰视",glossary:"zby_light_shushi"},"其状貌：",{text:"窨然空然",glossary:"zby_light_yinran"},"。"]]},{id:"zby_light_s2",label:"视不见，听不闻，搏不得",sentences:[["终日视之而不见，听之而不闻，",{text:"搏之而不得",glossary:"zby_light_bo"},"也。"]]},{id:"zby_light_s3",label:"能有无而未能无无：何从至此",sentences:[["光曜曰：「至矣，其孰能至此乎！",{text:"予能有无矣",glossary:"zby_light_youwu"},"，而",{text:"未能无无",glossary:"zby_light_wuwu"},"也。"],["及为无有矣，",{text:"何从至此",glossary:"zby_light_hecong"},"哉！」"]]}],v=[{id:"zby_light_guangyao",term:"光曜",pinyin:"guāng yào",meaning:"寓言人物名，借明照之义，本篇向无有发问，构成有无张力的问答。不将其列为修养体系中的固定等级。"},{id:"zby_light_wuyou",term:"无有",pinyin:"wú yǒu",meaning:"寓言人物名，借无有之义。与光曜问答，呈现有无与无无的层层追问，不是可据以自立的境界标签。"},{id:"zby_light_shushi",term:"孰视",pinyin:"shú shì",meaning:"仔细看、熟视。孰联系熟理解。不得问：未获得所问的回答，不必等同不能再提出问题。"},{id:"zby_light_yinran",term:"窨然空然",pinyin:"yìn rán kōng rán",meaning:"幽深、空寂的样子。窨的读音与字形可依底本统一，不把空然解释成心理空虚。"},{id:"zby_light_bo",term:"搏之而不得",pinyin:"bó zhī ér bù dé",meaning:"抓取、执取而不能得到。与视、听并列，检验把所问当作可感可取对象的方式。"},{id:"zby_light_youwu",term:"予能有无矣",pinyin:"yǔ néng yǒu wú yǐ",meaning:"能够以无为所知、所持，或能够知有无等，有不同解释。关键在有无尚与未能无无相对，不简单译成已经达到高级境界。"},{id:"zby_light_wuwu",term:"未能无无",pinyin:"wèi néng wú wú",meaning:"尚不能连所执的无也松开。可联系不再以无为一个可据有的对象理解，不需要继续无限添加否定词才算通达。"},{id:"zby_light_hecong",term:"何从至此",pinyin:"hé cóng zhì cǐ",meaning:"怎样能够到达这里？保留光曜的感叹与追问，原文未给出最后的步骤答案。"}],T=[{id:"zby_craft_s1",label:"八十不失豪芒：巧与道",sentences:[[{text:"大马",glossary:"zby_craft_dama"},"之捶钩者，年八十矣，而不失",{text:"豪芒",glossary:"zby_craft_haomang"},"。"],["大马曰：「子巧与？有道与？」"]]},{id:"zby_craft_s2",label:"臣有守：非钩无察",sentences:[["曰：「",{text:"臣有守也",glossary:"zby_craft_shou"},"。臣之年二十而好捶钩，于物无视也，非钩无察也。"],["是用之者，",{text:"假不用者",glossary:"zby_craft_buyong"},"也，以长得其用。」"]]},{id:"zby_craft_s3",label:"轮扁斫轮：此类是也",sentences:[["又有",{text:"轮扁斫轮",glossary:"zby_craft_lunbian"},"之说，此类是也。"]]}],S=[{id:"zby_craft_dama",term:"大马",pinyin:"dà mǎ",meaning:"传统常联系大司马这一官名理解。捶钩：锻打带钩等器物；钩的具体用途宜依注本处理，不强定为鱼钩。"},{id:"zby_craft_haomang",term:"不失豪芒",pinyin:"bù shī háo máng",meaning:"不失毫芒之细，形容制作仍精细准确。豪通毫；不是说八十岁者身体机能完全不衰。"},{id:"zby_craft_shou",term:"臣有守也",pinyin:"chén yǒu shǒu yě",meaning:"我有所守持。下文用长期专注说明所守，不直接宣称已取得全部至道。"},{id:"zby_craft_buyong",term:"假不用者",pinyin:"jiǎ bù yòng zhě",meaning:"借助不用于他事的注意与心力，成就此处之用。假：借助。不用与无用不完全同义，不宜直接等同无用之用。"},{id:"zby_craft_lunbian",term:"轮扁斫轮",pinyin:"lún biǎn zhuó lún",meaning:"《庄子·天道》中的工匠故事。斫：砍削。此处明确提及同类之说，但不足以确定两篇的单向写作或引用先后。"}],A=[{id:"zby_ran_s1",label:"未有天地可知乎：古犹今也",sentences:[[{text:"冉求",glossary:"zby_ran_people"},"问于仲尼曰：「未有天地可知乎？」"],["仲尼曰：「可。古犹今也。」冉求",{text:"失问而退",glossary:"zby_ran_shiwen"},"。"]]},{id:"zby_ran_s2",label:"昔日昭然，今日昧然",sentences:[["明日复见，曰：「昔者吾问『未有天地可知乎』，夫子曰『可，古犹今也』。"],["昔日吾昭然，今日吾昧然，敢问何谓也？」"]]},{id:"zby_ran_s3",label:"神者先受之：古今与始终",sentences:[["仲尼曰：「昔之昭然也，",{text:"神者先受之",glossary:"zby_ran_shen"},"；今之昧然也，且又为不神之累也。"],["无古无今，无始无终。",{text:"未有子孙而有子孙，可乎",glossary:"zby_ran_zisun"},"？」冉求未对。"]]},{id:"zby_ran_s4",label:"死生与一体：不以一端说明另一端",sentences:[["仲尼曰：「已矣，未应矣！",{text:"不以生生死，不以死死生",glossary:"zby_ran_shengsi"},"。"],["死生有待邪？皆有所一体。"]]},{id:"zby_ran_s5",label:"物物者非物：道无以名",sentences:[["有先天地生者物邪？",{text:"物物者非物",glossary:"zby_ran_wuwu"},"，",{text:"物不得先物也",glossary:"zby_ran_xianwu"},"，"],[{text:"非物无止，非止无道",glossary:"zby_ran_feizhi"},"，",{text:"道无以名",glossary:"zby_ran_wuming"},"。」"]]}],C=[{id:"zby_ran_people",term:"冉求",pinyin:"rǎn qiú",meaning:"孔子弟子，字子有。本段按寓言问答阅读，不必当作可精确复原的课堂记录。"},{id:"zby_ran_shiwen",term:"失问而退",pinyin:"shī wèn ér tuì",meaning:"未能继续发问或忘其所问而退，具体解释有差异。不能据此认定冉求已经完成通达。"},{id:"zby_ran_shen",term:"神者先受之",pinyin:"shén zhě xiān shòu zhī",meaning:"精神先有所领受、相契等。神与不神的对比不能直接套成现代直觉与分析的严格二分，也不证明直觉必然正确。"},{id:"zby_ran_zisun",term:"未有子孙而有子孙，可乎",pinyin:"wèi yǒu zǐ sūn ér yǒu zǐ sūn, kě hū",meaning:"以子孙未生与已生反问生成关系。句意有解释空间，不直接断言未有与已有同时发生，或现实时间不存在。"},{id:"zby_ran_shengsi",term:"不以生生死，不以死死生",pinyin:"bù yǐ shēng shēng sǐ, bù yǐ sǐ sǐ shēng",meaning:"生、死在句中有名词与动词作用，具体训释有争议。可先把握不以一端作为另一端的充分生成根据，不用含混的生死互换替代解释。"},{id:"zby_ran_wuwu",term:"物物者非物",pinyin:"wù wù zhě fēi wù",meaning:"使物成为物的生成根本，并不是同类的一件物。不能简单设成在时间上更早出现的第一件物。"},{id:"zby_ran_xianwu",term:"物不得先物也",pinyin:"wù bù dé xiān wù yě",meaning:"具体物不能作为一切物的绝对先在根本等，有不同解释。不能据此直接证明道是时间序列中最早的一件实体。"},{id:"zby_ran_feizhi",term:"非物无止，非止无道",pinyin:"fēi wù wú zhǐ, fēi zhǐ wú dào",meaning:"疑难句，非可作非、非有等不同理解，止亦有止处、界限、定止等解释。不在此强定为没有限制就没有道；应连同物物者非物与道无以名理解。"},{id:"zby_ran_wuming",term:"道无以名",pinyin:"dào wú yǐ míng",meaning:"道不能被名称充分确定。不是因为不能充分命名，就无法作任何说明；本段仍以问答展开辨析。"}],j=[{id:"zby_change_s1",label:"无有所将，无有所迎：问其游",sentences:[["颜渊问乎仲尼曰：「回尝闻诸夫子曰：『",{text:"无有所将，无有所迎",glossary:"zby_change_jiangying"},"。』回敢问其游。」"],["仲尼曰：「古之人，",{text:"外化而内不化",glossary:"zby_change_neiwai"},"；今之人，内化而外不化。"]]},{id:"zby_change_s2",label:"与物化与不化：安与相靡",sentences:[["与物化者，一不化者也。",{text:"安化安不化",glossary:"zby_change_anhua"},"，安与之相靡，必与之莫多。"]]},{id:"zby_change_s3",label:"古代境域与儒墨是非",sentences:[[{text:"狶韦氏之囿",glossary:"zby_change_xiwei"},"，黄帝之圃，有虞氏之宫，汤武之室。"],["君子之人，若儒墨者师，故",{text:"以是非相赀",glossary:"zby_change_zi"},"也，而况今之人乎！"]]},{id:"zby_change_s4",label:"处物不伤物：相将迎",sentences:[["圣人处物不伤物。",{text:"不伤物者，物亦不能伤",glossary:"zby_change_bushang"},"也。"],["唯无所伤者，为能与人相将迎。"]]},{id:"zby_change_s5",label:"山林皋壤：哀乐来去",sentences:[["山林与！",{text:"皋壤",glossary:"zby_change_gaorang"},"与！使我欣欣然而乐与！"],["乐未毕也，哀又继之。哀乐之来，吾不能御，其去弗能止。"],["悲夫，世人直为物",{text:"逆旅",glossary:"zby_change_nilv"},"耳！"]]},{id:"zby_change_s6",label:"知遇与知能：不能尽免人的限度",sentences:[["夫知遇而不知所不遇，知能能而不知所不能。"],["无知无能者，固",{text:"人之所不免",glossary:"zby_change_bumian"},"也。夫务免乎人之所不免者，岂不亦悲哉！"]]},{id:"zby_change_s7",label:"至言去言，至为去为：不以已知为全部",sentences:[[{text:"至言去言，至为去为",glossary:"zby_change_zhiyan"},"，",{text:"齐知之所知",glossary:"zby_change_qizhi"},"，则浅矣。」"]]}],V=[{id:"zby_change_jiangying",term:"无有所将，无有所迎",pinyin:"wú yǒu suǒ jiāng, wú yǒu suǒ yíng",meaning:"将常联系送理解。可联系不预先追送、迎取，不以执持规定来往；与后文相将迎连读，不是永远拒绝人际往来。"},{id:"zby_change_neiwai",term:"外化而内不化",pinyin:"wài huà ér nèi bù huà",meaning:"外在随情势而变，内在不被情势夺其根本。与今之人内化外不化相对，不直接证明存在一个永远不变的实体灵魂。"},{id:"zby_change_anhua",term:"安化安不化",pinyin:"ān huà ān bù huà",meaning:"安有何、焉的疑问用法，也有联系安处者，整句存在不同解释。不直接把三个安都定为顺安；相靡、莫多亦宜依注本校定。"},{id:"zby_change_xiwei",term:"狶韦氏之囿",pinyin:"xī wéi shì zhī yòu",meaning:"借古代帝王的苑囿、宫室列出不同历史境域。狶韦氏具体身份不在此坐实，不把这些境域都改成现实可考地点。"},{id:"zby_change_zi",term:"以是非相赀",pinyin:"yǐ shì fēi xiāng zī",meaning:"以是非相计、相较，亦有相诋等解释。赀的具体义项有讨论空间，重点在争执的彼此关系。"},{id:"zby_change_bushang",term:"不伤物者，物亦不能伤",pinyin:"bù shāng wù zhě, wù yì bù néng shāng",meaning:"理想化地描写不侵伤、不强作的相处。不是现实中的免伤规律，不能据此说受害者必定先伤害他人。"},{id:"zby_change_gaorang",term:"皋壤",pinyin:"gāo rǎng",meaning:"水边高地、岸边土地等。山林与、皋壤与中的与为感叹语气，可读 yú。"},{id:"zby_change_nilv",term:"逆旅",pinyin:"nì lǚ",meaning:"旅舍、客栈。以人如外物、哀乐来去的居处作譬喻，不等于人全无回应能力。"},{id:"zby_change_bumian",term:"人之所不免",pinyin:"rén zhī suǒ bù miǎn",meaning:"人不可彻底消除的未知、不能与生命条件。不等于具体困难都无法改善，也不要求停止学习和求助。"},{id:"zby_change_zhiyan",term:"至言去言，至为去为",pinyin:"zhì yán qù yán, zhì wéi qù wéi",meaning:"最通达的言与为，解除对言与为的拘执、造作。保留其反常表达，不简单改成最高境界就是永不说话、永不行动。"},{id:"zby_change_qizhi",term:"齐知之所知",pinyin:"qí zhī zhī suǒ zhī",meaning:"齐有限齐、止于等解释。若以现有认识所能知为全部，便浅；不是说一切知识本身都浅薄无用。"}];return(L,n)=>{const I=p("DaoReadingPrelude"),s=p("DaoTextReading"),r=p("DaoKeywordCards"),d=p("DaoLineGuide");return N(),E("div",null,[n[0]||(n[0]=i("",10)),a(I,{title:"先读前四段：从求知求得，到不强作与不据有",summary:"知的三次问道检验认知与言说的限度；天地大美把视野转向不借语言而生成的秩序；啮缺睡寐使求道教学发生反转；舜与丞的问答则追问，连身体与生命都有所依待，道又怎能被占为己有？",points:[{label:"先看",text:"不知、忘之、知之，为什么在这则寓言中得到反常评价？"},{label:"再问",text:"黄帝仍然长篇作答，天地之理仍被探究，这是否限制了对反知反言的简单理解？"},{label:"最后",text:"不把道据为己有，与放弃判断、照料身体和承担责任，有什么区别？"}],hint:"全篇十二段均已整理：前四段立起「知与言都有其限度」的问题，五至九段转入道之无所不在与论道非道，末三段再落到具体技艺、古今变化与人的限度；文末脉络逻辑链、三问解读、现代启发与关键词索引覆盖全篇。"}),n[1]||(n[1]=t("h2",{id:"一、知的三次问道·不知、忘之与知之",tabindex:"-1"},[e("一、知的三次问道·不知、忘之与知之 "),t("a",{class:"header-anchor",href:"#一、知的三次问道·不知、忘之与知之","aria-label":'Permalink to "一、知的三次问道·不知、忘之与知之"'},"​")],-1)),n[2]||(n[2]=t("h3",{id:"原文",tabindex:"-1"},[e("原文 "),t("a",{class:"header-anchor",href:"#原文","aria-label":'Permalink to "原文"'},"​")],-1)),a(s,{sections:o,glossary:y,"default-mode":"classic","aria-label":"知北游·知的三次问道 原文"}),n[3]||(n[3]=t("h3",{id:"生僻字词",tabindex:"-1"},[e("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(r,{items:[{term:"知",pinyin:["zhī / zhì"],meaning:"寓言人物名，关联认知与智识，读音依注本统一。"},{term:"隐弅",pinyin:["yǐn","fèn"],meaning:"篇中的丘名。"},{term:"无为谓",pinyin:["wú","wéi","wèi"],meaning:"寓言人物，以不知答呈现一种不据知而言的状态。"},{term:"若",pinyin:["ruò"],meaning:"你。予欲有问乎若：我想问你。"},{term:"反",pinyin:["fǎn"],meaning:"返回。"},{term:"道之华",pinyin:["dào","zhī","huá"],meaning:"道的外在文饰、浮华。"},{term:"日损",pinyin:["rì","sǔn"],meaning:"逐日减损强作与执持等。"},{term:"纪",pinyin:["jì"],meaning:"条理、纲纪。"},{term:"死生为徒",pinyin:["sǐ","shēng","wéi","tú"],meaning:"死生相伴，同在变化之中。"},{term:"臭腐",pinyin:["chòu","fǔ"],meaning:"腐臭之物，与人所美的神奇相对。"}]}),n[4]||(n[4]=t("h3",{id:"核心句引读",tabindex:"-1"},[e("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(d,{title:"不是少知道一些就更高明，而是检验把道变成可把握对象的求知",subtitle:"黄帝的回答有作用，却也承认回答不能穷尽所求。",lines:[{text:"何思何虑则知道？何处何服则安道？何从何道则得道？",tone:"求问",guide:"三问分别涉及认知、处身与道路，都期待明确条件。故事将这套期待反转，但不能推出询问方法本身永远错误。第三段被衣就提出正形、一视、摄知等指引。问题更适宜放在：是否以为找到固定步骤，就能把道作为结果取得。"},{text:"非不答，不知答也。",tone:"不知",guide:"无为谓不是故意拒答，而是不知如何答。寓言给予这种状态特殊肯定，不能据此普遍赞美知识不足，也不能把普通困惑自动认成得道。它检验的是不以已知据有道的状态，而不是建立越无知越正确的规则。"},{text:"彼无为谓真是也，狂屈似之，我与汝终不近也。",tone:"判定",guide:"本段明确把不知列为真是、忘之列为似之、知之列为不近。因此不能反说忘比不知更接近。狂屈曾经要说而忘，黄帝能够说却承认不近，三种回应形成反常比较。这个比较限定于问道寓言，不可直接用来评价所有知识与表达。"},{text:"无思无虑始知道，无处无服始安道，无从无道始得道。",tone:"松开",guide:"回答在形式上逐一对应三问，却取消了求问者期待的固定凭借。可联系不以思虑、处身套路和路径执持来据有道理解。不是要求大脑停止一切活动，也不等于任何行动都不需判断与准备。"},{text:"知者不言，言者不知。",tone:"言知",guide:"强烈对举指出真实通达不能被已说出的命题穷尽。但黄帝正借言说指出这一限度，末句狂屈又称他知言。文本保留了以言显限的张力，不宜把所有发言者判为不知。此句亦见《老子》，并非知者不博的简单改写。"},{text:"失道而后德……礼者，道之华而乱之首也。",tone:"失根",guide:"这里确实对仁义礼的递降与相伪提出尖锐批评，不能完全化成温和的形式与内容区别。阅读可关注：整体通达失落后，外在德目与仪节如何成为补偿、争执和伪饰。与此同时，也不必把每一次仁爱、礼让都认作虚伪行为。"},{text:"损之又损之，以至于无为。无为而无不为也。",tone:"日损",guide:"日损不是减少一切能力，而是松开强求、刻意造作与对已知的据执。无不为是理想化表达，不是无所不能的成功保证。能不强作，与能妥善回应事物可以相通；具体事务仍需分辨条件。"},{text:"人之生，气之聚也。聚则为生，散则为死。",tone:"聚散",guide:"以气之聚散把生死放回生成变化中，缓解只贵一端的执持。这是古代生成论，不直接等同现代物理学，也不能证明气散后个人记忆与意识继续存在。死亡的事实没有因此取消。"},{text:"臭腐复化为神奇，神奇复化为臭腐。通天下一气耳。",tone:"相化",guide:"人所美、所恶的状态能够互化，说明评价对象并非永久固定。贵一可联系重视贯通变化的整体，而不是说美恶、大小和个体差异全无意义。相通不必等于同一状态。"},{text:"狂屈闻之，以黄帝为知言。",tone:"余味",guide:"结尾并未简单让黄帝的言说全部失效。狂屈肯定其知言，与前文知者不言形成张力：可以用语言指出语言的限度，却不能因此据称已经穷尽道。故事既反省言说，也仍借言说开启反省。"}]}),n[5]||(n[5]=i("",8)),a(s,{sections:l,glossary:g,"default-mode":"classic","aria-label":"知北游·天地大美与本根 原文"}),n[6]||(n[6]=t("h3",{id:"生僻字词-1",tabindex:"-1"},[e("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词-1","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(r,{items:[{term:"成理",pinyin:["chéng","lǐ"],meaning:"形成、运行所具的条理。"},{term:"原",pinyin:["yuán"],meaning:"推原、探究或本于。"},{term:"百化",pinyin:["bǎi","huà"],meaning:"纷繁的变化。"},{term:"六合",pinyin:["liù","hé"],meaning:"上下四方。"},{term:"秋豪",pinyin:["qiū","háo"],meaning:"通秋毫，极细小之物。"},{term:"沈浮",pinyin:["chén","fú"],meaning:"沉浮、变化起伏。"},{term:"不故",pinyin:["bù","gù"],meaning:"不保持旧状等，不只指不停止。"},{term:"惛然",pinyin:["hūn","rán"],meaning:"幽昧难辨的样子。"},{term:"畜",pinyin:["xù"],meaning:"养育。"},{term:"本根",pinyin:["běn","gēn"],meaning:"生成与变化所依的根本。"}]}),n[7]||(n[7]=t("h3",{id:"核心句引读-1",tabindex:"-1"},[e("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读-1","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(d,{title:"天地不借语言自陈，却仍值得观察、推原与通达",subtitle:"不言不是没有条理，无为不是没有生成。",lines:[{text:"天地有大美而不言，四时有明法而不议，万物有成理而不说。",tone:"有而不言",guide:"三个有与三个不相对：美、法、理并不等到被言说才成立。天地不是像人一样知道一切却保持沉默，而是其生成秩序不依语言发布。这里把视野从人的问答转向万物自身的发生。"},{text:"原天地之美而达万物之理。",tone:"通达",guide:"圣人的方向仍包含推原与通达。这限制了只把全篇读成停止思考的解释：观察事物、理解条理仍有作用，只是不把概念说明当成天地本身，也不以私意替代其发生条件。"},{text:"至人无为，大圣不作，观于天地之谓也。",tone:"取法",guide:"无为、不作与观天地连在一起，可理解为不妄兴、不强加。天地并非没有变化与生成，因此取法天地也不等于什么都不做。不能用自然之理为一切现存社会制度作伦理背书。"},{text:"六合为巨，未离其内；秋豪为小，待之成体。",tone:"大小",guide:"最大的空间与最细微的成体，都被放在同一生成根本中。大小差异仍然存在，强调的是都非无所依待的独立之物，不是把宇宙与毫毛说成尺寸相同。"},{text:"惛然若亡而存；油然不形而神。",tone:"难见",guide:"本根难以指认，仿佛无而又有所存，无特定形体却有神妙作用。词句描述认识上的难见与作用上的相通，不必把它设成一个隐藏物体，也不宜直接转成可验证的超自然实体。"},{text:"万物畜而不知：此之谓本根，可以观于天矣！",tone:"本根",guide:"万物得到养育，却未必知道所以然；也有将不知联系养育作用本身的解释。结尾把观察引向根本，不是宣布必须以直觉取代所有证据。观可以包含察看、体认与取法，仍需分辨所能说明的范围。"}]}),n[8]||(n[8]=i("",11)),a(s,{sections:h,glossary:b,"default-mode":"classic","aria-label":"知北游·啮缺与被衣 原文"}),n[9]||(n[9]=t("h3",{id:"生僻字词-2",tabindex:"-1"},[e("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词-2","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(r,{items:[{term:"啮缺",pinyin:["niè","quē"],meaning:"《庄子》中的问道人物。"},{term:"被衣",pinyin:["pī","yī"],meaning:"篇中指导啮缺的人物，读音依注本统一。"},{term:"摄",pinyin:["shè"],meaning:"收摄、收敛。"},{term:"度",pinyin:["dù"],meaning:"心度、度量等。"},{term:"舍",pinyin:["shè"],meaning:"安住。神将来舍。"},{term:"犊",pinyin:["dú"],meaning:"小牛。"},{term:"卒",pinyin:["zú"],meaning:"结束。言未卒：话未说完。"},{term:"说",pinyin:["yuè"],meaning:"通悦，高兴。"},{term:"槁骸",pinyin:["gǎo","hái"],meaning:"枯槁的形骸。"},{term:"媒媒晦晦",pinyin:["méi","méi","huì","huì"],meaning:"幽昧、不显智巧的样子。"}]}),n[10]||(n[10]=t("h3",{id:"核心句引读-2",tabindex:"-1"},[e("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读-2","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(d,{title:"不以机故自持，不等于完全失去认识与生命活力",subtitle:"睡寐是寓言反转，不是得道测试。",lines:[{text:"正汝形，一汝视……摄汝知，一汝度。",tone:"收摄",guide:"被衣确实给出具体指引，先从形、视，再到知、度。它与第一段对固定方法的反省形成张力：指引可以帮助减少散乱，但不必成为取得道的机械程序。正形不只是外在表演，摄知也不是把全部知识消除。"},{text:"神将来舍。德将为汝美，道将为汝居。",tone:"安住",guide:"以神来舍、道为居描写安顿，可联系收摄后的整合与不强逐理解，不必解释成某个神灵实际进入身体。将字保留一种指引的语气，不是任何人照做都保证发生的生理结果。"},{text:"如新生之犊而无求其故。",tone:"初生",guide:"新生小牛的譬喻突出朴直、未被机故拘持的状态。无求其故可联系不追执所以然，不是对科学研究、学习提问发出禁令。第二段仍说原天地之美、达万物之理，认识须按语境区分。"},{text:"言未卒，啮缺睡寐。被衣大说。",tone:"反转",guide:"听者没有以持续追问回应，而进入睡眠，教者反而喜悦。这让成功教学不等于知识答题的故事预期发生变化。但不能把现实课堂睡着、疲劳或意识异常认成得道，也不应据此忽略睡眠与健康问题。"},{text:"形若槁骸，心若死灰，真其实知。",tone:"真知",guide:"外在静止与真知并列，不能简单等同真的死亡或心脏停跳。与《田子方》哀莫大于心死对读，相近的死亡譬喻可以承担不同作用：一处警惕心的死滞，一处松开机心强逐。不能仅按字面把两处合成同一心理状态。"},{text:"不以故自持……无心而不可与谋。",tone:"不自持",guide:"不以成故、机故固持自身，不以机心参与筹谋，是歌辞可把握的方向。它不是不守承诺、无法合作的理想，也不等于过去所有经验都有害。所松开的是以旧见和机巧占满自身。"}]}),n[11]||(n[11]=i("",10)),a(s,{sections:_,glossary:u,"default-mode":"classic","aria-label":"知北游·舜与丞 原文"}),n[12]||(n[12]=t("blockquote",null,[t("p",null,"**整理说明：**来稿本段原文完整，后附解读在末尾截断。以下依据原文整理，不将未收到的部分补作原稿。")],-1)),n[13]||(n[13]=t("h3",{id:"生僻字词-3",tabindex:"-1"},[e("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词-3","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(r,{items:[{term:"丞",pinyin:["chéng"],meaning:"篇中舜的问答对象，具体身份有不同解释。"},{term:"有",pinyin:["yǒu"],meaning:"此处联系占有、据为己有理解。"},{term:"委形",pinyin:["wěi","xíng"],meaning:"天地所委聚、所赋的形体。"},{term:"委和",pinyin:["wěi","hé"],meaning:"天地生成的和气、生命之和。"},{term:"委顺",pinyin:["wěi","shùn"],meaning:"天地所赋、所循的性命之顺。"},{term:"委蜕",pinyin:["wěi","tuì"],meaning:"天地变化中的形体相续。"},{term:"强阳气",pinyin:["qiáng","yáng","qì"],meaning:"运行、动荡或强健之气，训释有空间。"},{term:"胡",pinyin:["hú"],meaning:"怎么。又胡可得而有邪：又怎能据有？"}]}),n[14]||(n[14]=t("h3",{id:"核心句引读-3",tabindex:"-1"},[e("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读-3","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(d,{title:"由身体与生命的依待，反问道怎能成为私有之物",subtitle:"不据有不取消身体自主，也不把子孙交给另一位绝对主人。",lines:[{text:"道可得而有乎？",tone:"占有",guide:"舜不只问能否知道道，还问能否得到并拥有。这把求问推进到占有：道是否像某件财物、某项成就一样，可以划归自己？丞由身体反问，松开以个人为绝对所有者的预设。"},{text:"汝身非汝有也，汝何得有夫道！",tone:"反问",guide:"身体生成、存续依赖天地与众多条件，不是自我从无到有独自制造并完全控制的东西。哲学上的非汝有，不应转成别人可以侵害身体、取消同意或剥夺身体自主的理由。它质疑绝对据有，不为现实侵犯提供许可。"},{text:"天地之委形……委和……委顺……委蜕。",tone:"所依",guide:"四个委把形体、生命、性命与子孙放回天地生成。委可联系委聚、委付，不必设定人格化天地签署委托合同、随时收回资产。子孙非汝有尤其不能解释成孩子只是父母或天地的财物：生命相续并不赋予绝对支配权。"},{text:"行不知所往，处不知所持，食不知所味。",tone:"日常",guide:"三个不知把占有问题放回行、处、食，可联系不以自我筹计和分别固执生活理解。句意有解释空间，不能作为不辨方向、不坚持任何原则或不管饮食安全的指令。不据有与妥善照料生命可以并行。"},{text:"天地之强阳气也，又胡可得而有邪！",tone:"气化",guide:"以天地运行之气收束，说明生命不是完全独立于变化的私物。强阳气不必只指阴阳中的阳，也不能据此把道简化成一种可测量物质。回到最初问题：与道相通，不等于把道圈成自己的所有物。"}]}),n[15]||(n[15]=i("",19)),a(s,{sections:m,glossary:z,"default-mode":"classic","aria-label":"知北游·孔子问老聃 原文"}),n[16]||(n[16]=t("blockquote",null,[t("p",null,[t("strong",null,"阅读说明："),e("「中国有人焉」「喑噫物」「明见无值」等有训释空间。下文依整段论述梳理，不把生成描述直接画成已确定的科学流程，也不以「大归」证明个人意识永存。")])],-1)),n[17]||(n[17]=t("h3",{id:"生僻字词-4",tabindex:"-1"},[e("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词-4","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(r,{items:[{term:"晏闲",pinyin:["yàn","xián"],meaning:"安闲、有暇。"},{term:"齐戒",pinyin:["zhāi","jiè"],meaning:"通斋戒，收摄身心。"},{term:"疏瀹",pinyin:["shū","yuè"],meaning:"疏通、洗涤。"},{term:"澡雪",pinyin:["zǎo","xuě"],meaning:"洗涤、清理，不是降雪。"},{term:"掊击",pinyin:["pǒu","jī"],meaning:"击破、消解，文中为智识执持的譬喻。"},{term:"崖略",pinyin:["yá","lüè"],meaning:"大概轮廓。"},{term:"恂达",pinyin:["xún","dá"],meaning:"顺畅通达等。"},{term:"魏魏",pinyin:["wēi","wēi"],meaning:"巍然高大的样子。"},{term:"果蓏",pinyin:["guǒ","luǒ"],meaning:"木本、草本所结果实等。"},{term:"天帙",pinyin:["tiān","zhì"],meaning:"天然包裹的譬喻，帙本指书衣等。"},{term:"大归",pinyin:["dà","guī"],meaning:"生命归入变化根本的表达。"},{term:"塞",pinyin:["sè"],meaning:"闭塞，闻不若塞，不宜只按耳塞名词读音处理。"}]}),n[18]||(n[18]=t("h3",{id:"核心句引读-4",tabindex:"-1"},[e("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读-4","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(d,{title:"以长篇说明打开认识，又不让说明成为对道的完全据有",subtitle:"先言崖略，后言辩不若默，二者构成整段张力。",lines:[{text:"疏瀹而心，澡雪而精神，掊击而知。",tone:"清理",guide:"老聃先要求清理身心和所据执的智识，再开始说明。掊击语气强烈，不能完全弱化成普通整理，但也不应按字面理解为毁坏认知能力。它针对问者带来的固定尺度与自以为已知，不等于知识、判断、学习一概有害。"},{text:"夫道，窨然难言哉！将为汝言其崖略。",tone:"崖略",guide:"承认难言，却仍尝试言说大概。说明不是道本身，也不因此失去全部作用。与开篇黄帝的长篇回答相接，文本并不只有沉默，还反复运用言说来提示言说的限度。"},{text:"精神生于道，形本生于精，而万物以形相生。",tone:"生成",guide:"段落从明与冥、有伦与无形转入精、形与万物，指向生成的根本。精神与精的含义彼此有关，原文没有在两者之间明确写出独立阶段，不能擅自画成道、精神、精气、形体的严格单线流程。九窍胎生、八窍卵生属于古代论说，也不直接作为现代生物学分类。"},{text:"其用心不劳，其应物无方。",tone:"应物",guide:"前面说思虑恂达、耳目聪明，说明清理智识之后并非昏聩无能。无方可联系不固守一法，能随情势回应。用心不劳是通达的理想，不保证身体永不疲劳，也不把疾病归因于未能得道。"},{text:"博之不必知，辩之不必慧。",tone:"博辩",guide:"两个不必限定了判断：博学不保证真知，善辩不保证智慧，而不是所有博学者都无知、所有论辩都应放弃。圣人以断之的具体解释有空间，可以先把握不将资料数量与论辩优势直接当成通达。"},{text:"益之而不加益，损之而不加损者，圣人之所保也。",tone:"所保",guide:"所保之根本不能按通常的增减占有来计算。与第一段日损连读，需要分清减损的是强作与执持，不是把道削得更小；所保不以增减计，也不意味着人的钱、时间与健康不会耗损。"},{text:"直且为人，将反于宗。",tone:"为人",guide:"人被放回生成变化中，人的形态不是一切变化的终点。非阴非阳、中国有人等字句不宜被强定为某位超越阴阳的神人。反于宗表达回归根本，不直接证明死亡后同一人格仍继续存在。"},{text:"圣人遭之而不违，过之而不守。",tone:"时应",guide:"遭遇时妥善回应，事过后不固守已经发生的样子。不违不是无条件服从任何人伦秩序，不守也不是放弃承诺和责任。调、偶可联系调和与相配，不必给二者规定有意识、无意识的固定等级。"},{text:"人生天地之间，若白驹之过隙，忽然而已。",tone:"流逝",guide:"白驹过隙把个体一生放到更广大的时间尺度中。寿夭相较为须臾，也是在自本观之的视角中展开。不能把这种尺度转换直接用于否定早逝者的损失，或认定尧桀之间的现实伤害全都不重要。"},{text:"已化而生，又化而死……乃大归乎！",tone:"大归",guide:"生死都被描述为化，大归使死亡不只被理解为私有生命遭到夺取。原文同时写生物哀之、人类悲之，并未把哀伤完全删除。归的譬喻可以缓解执持，却不是个人意识不灭、死后必定回家的事实承诺。"},{text:"彼至则不论，论则不至……此之谓大得。",tone:"言限",guide:"末尾确实尖锐地限制论、辩、闻，不能把它改成原文完全肯定议论。但整段又通过问答说明崖略，因此应保留其张力：以论说代替所通达者，会困在所说之中；论说作为引导，则不能被认成最终所得。大得不是单纯少听少说的行为测试。"}]}),n[19]||(n[19]=i("",8)),a(s,{sections:c,glossary:x,"default-mode":"classic","aria-label":"知北游·道无所不在 原文"}),n[20]||(n[20]=t("h3",{id:"生僻字词-5",tabindex:"-1"},[e("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词-5","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(r,{items:[{term:"恶乎在",pinyin:["wū","hū","zài"],meaning:"在哪里。恶读 wū。"},{term:"期",pinyin:["qī"],meaning:"指定、限定。"},{term:"稊稗",pinyin:["tí","bài"],meaning:"杂草、似禾之草。"},{term:"甓",pinyin:["pì"],meaning:"砖。"},{term:"溺",pinyin:["niào"],meaning:"此处指尿，不读溺水之 nì。"},{term:"狶",pinyin:["xī"],meaning:"猪。"},{term:"每下愈况",pinyin:["měi","xià","yù","kuàng"],meaning:"向下察验，反而更能明白情况。"},{term:"咸",pinyin:["xián"],meaning:"都、全。"},{term:"冯闳",pinyin:["féng","hóng"],meaning:"广大、空旷的境域或状态。"},{term:"际",pinyin:["jì"],meaning:"边际、界限或相接。"},{term:"衰杀",pinyin:["shuāi","shài"],meaning:"衰退、减杀。杀在减杀义常读 shài。"}]}),n[21]||(n[21]=t("h3",{id:"核心句引读-5",tabindex:"-1"},[e("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读-5","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(d,{title:"不因贵贱洁秽划定道的所在，也不把道等同某一件物",subtitle:"无所不在与物物者不是某物，须同时理解。",lines:[{text:"所谓道，恶乎在？……无所不在。",tone:"所在",guide:"东郭子期待一个可指定的位置，庄子先以无所不在回答。问题不只在问在哪里，而在期而后可：问者要求道必须被圈到一处才能成立。不能因此说所有关于位置的提问都无意义。"},{text:"在蝼蚁……在稊稗……在瓦甓……在屎溺。",tone:"低处",guide:"回答依问者的评价不断向下，直到排泄物，打破只有高贵、洁净、生命之物才能与道相关的预设。不是说污秽等于神圣，也不取消饮食卫生和价值判断。所反对的是以这些判断排除生成根本的普遍性。"},{text:"每下愈况。汝唯莫必。",tone:"察验",guide:"察猪肥瘦的比喻强调向难显肥处察验，反而更能明白情形。正、获的身份与句读有讨论空间，不必编成两位屠夫的完整故事。莫必首先是不必定道只在某类所在，不是要求生活中永不作确定判断。"},{text:"周遍咸三者，异名同实，其指一也。",tone:"名称",guide:"周、遍、咸共同说明普遍与全体。不同名称可以指向相近意思，不能由此宣布所有概念都同义。这个细节也显示庄子仍然使用、解释语言，而不是仅仅要求沉默。"},{text:"尝相与游乎无有之宫，同合而论。",tone:"共游",guide:"尝在此可作试、姑且理解，是邀请共游，不一定是在回忆曾有经历。尤其值得注意同合而论：第五段刚限制论说，这里又提出共同讨论。两处须按是否把言说据为终极来辨，不宜一律归成所有论说都离道。"},{text:"无往焉而不知其所至……大知入焉而不知其所穷。",tone:"所至与所穷",guide:"第一句依现有文字有双重否定，不能直接译成到哪里都不知道。后面不知所止、所终、所穷，又强调不以终点与边界固定其游。可以辨明局部所至与根本所穷的不同，同时保留字句衔接的疑难。"},{text:"物物者与物无际，而物有际。",tone:"际",guide:"生成事物的根本不被某一物的边际圈住，具体事物却有区别与界限。道与物的关系不能只画成两个空间互相包含，更不应把无际解释成现实物体没有边界、人的权益不需区分。"},{text:"彼为盈虚非盈虚……彼为积散非积散也。",tone:"为与非",guide:"使盈虚、积散发生的根本，不就是某一次盈虚或积散。为可联系生成、使成理解，而不只是外表呈现。原文因此同时说普遍相通与不能等同某种状态：道不被限定在某物，也不能由一个变化名称穷尽。"}]}),n[22]||(n[22]=i("",9)),a(s,{sections:q,glossary:w,"default-mode":"classic","aria-label":"知北游·老龙吉之死 原文"}),n[23]||(n[23]=t("blockquote",null,[t("p",null,[t("strong",null,"阅读说明："),e("「无所发予之狂言」有不同解释。本段不据一个疑难词组建立“狂言是最高教法”的结论，也不把神农之笑规定为面对死亡必须采取的态度。")])],-1)),n[24]||(n[24]=t("h3",{id:"生僻字词-6",tabindex:"-1"},[e("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词-6","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(r,{items:[{term:"妸荷甘",pinyin:["ē","hé","gān"],meaning:"篇中与神农同学的人物，名字有异文异读。"},{term:"隐几",pinyin:["yǐn","jī"],meaning:"倚靠几案。"},{term:"阖户",pinyin:["hé","hù"],meaning:"关门。"},{term:"昼瞑",pinyin:["zhòu","míng"],meaning:"日间休息、睡眠。"},{term:"奓户",pinyin:["zhà","hù"],meaning:"打开门户，音义宜依注本统一。"},{term:"嚗然",pinyin:["bó","rán"],meaning:"突然、放杖有声等。"},{term:"谩诞",pinyin:["màn","dàn"],meaning:"漫诞、荒诞等。"},{term:"弇堈吊",pinyin:["yǎn","gāng","diào"],meaning:"篇中评论者的姓名。"},{term:"体道",pinyin:["tǐ","dào"],meaning:"体认、体现道。"},{term:"冥冥",pinyin:["míng","míng"],meaning:"幽暗难明，仍是一种论说用语。"}]}),n[25]||(n[25]=t("h3",{id:"核心句引读-6",tabindex:"-1"},[e("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读-6","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(d,{title:"连称道为冥冥，也仍是在论说，而非已经取得道",subtitle:"反常的失师回应，最后转入对语言的反省。",lines:[{text:"嚗然放杖而笑。",tone:"失师",guide:"听到老师之死，神农起身、放杖而笑，打破通常预期。随后的自嘲与遗憾说明笑不能直接等同毫无情感。也不应把不哭当成得道标准；真实哀伤并不因此成为过错。"},{text:"天知予僻陋谩诞……无所发予之狂言而死矣夫！",tone:"自述",guide:"话语中有对自身所知有限的感叹，也有失去老师的余味。发、予之狂言的具体关系有解释空间，不宜直接定为老师没能激发一套超越礼义的特殊言论，更不能把狂言与普通真知严格分级。"},{text:"秋豪之端万分未得处一焉，而犹知藏其狂言而死。",tone:"距离",guide:"以极细处的万分之一夸张所知之有限，又以藏言推进到体道者。这个比较强调不以所说据有道，不是实际量化某人掌握道的百分比，也不能推成越隐瞒知识越有德。"},{text:"视之无形，听之无声……所以论道而非道也。",tone:"论与所论",guide:"即使无形、无声、冥冥这些说法，也只是论道的语言，不是道本身。重要的是论说与所论的区别：地图不是地形，并不意味着地图完全无用。同样，谈论道不能代替体认，却不必因此取消所有说明。"}]}),n[26]||(n[26]=i("",9)),a(s,{sections:f,glossary:k,"default-mode":"classic","aria-label":"知北游·泰清问道 原文"}),n[27]||(n[27]=t("h3",{id:"生僻字词-7",tabindex:"-1"},[e("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词-7","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(r,{items:[{term:"泰清",pinyin:["tài","qīng"],meaning:"寓言中的问道人物。"},{term:"数",pinyin:["shù"],meaning:"条目、方法、条理等。"},{term:"约",pinyin:["yuē"],meaning:"收约、聚敛等。"},{term:"弗",pinyin:["fú"],meaning:"不。"},{term:"形形",pinyin:["xíng","xíng"],meaning:"使有形者成形，前一形有动词作用。"},{term:"当名",pinyin:["dàng","míng"],meaning:"与名称相当，不只指应该命名。"},{term:"无内",pinyin:["wú","nèi"],meaning:"缺乏真实内容、根本等，不是没有内心。"},{term:"大初",pinyin:["tài","chū"],meaning:"太初、生成之初。"},{term:"太虚",pinyin:["tài","xū"],meaning:"广大空虚的境域，具有譬喻作用。"}]}),n[28]||(n[28]=t("h3",{id:"核心句引读-7",tabindex:"-1"},[e("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读-7","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(d,{title:"能列举道的条目，不等于已经穷尽道",subtitle:"反省问答的预设，不是禁止所有提问。",lines:[{text:"无穷曰：吾不知。……无为曰：吾知道。",tone:"两答",guide:"本段再次并置不知与知道，但无穷已经用语言回答吾不知，不是从头到尾沉默。无为虽名无为，却被评价为浅、外，也提醒读者不能只按人物名字预定境界。"},{text:"可以贵、可以贱、可以约、可以散。",tone:"条目",guide:"无为能够说明若干状态、运用或条理。这些不必完全错误，问题在将它们列为自己已经知道道的根据。第六段已经区分使积散发生者与某次积散，知道若干变化不等于穷尽其根本。"},{text:"不知深矣，知之浅矣；弗知内矣，知之外矣。",tone:"深浅",guide:"内外深浅批评以条目化的已知据有道，肯定未把根本封闭为对象的不知。不能推成普通缺乏知识必然高于研究，也不宜把道画成有物理墙壁的内外空间。"},{text:"孰知不知之知？",tone:"再问",guide:"泰清不只是放弃认识，而是追问一种不同于据执已知的知。这个反问揭示反省还会继续，不能简单宣布逻辑上绝无答案、任何回应都必然失败。无始随后仍然继续解释。"},{text:"道不可闻……不可见……不可言。",tone:"三限",guide:"原文以强烈否定指出所闻所见所言不能当作道本身。不是道一旦被提及便真的变成非道，也不是观察万物都无意义；第二段仍说原天地之美、达万物之理。需要区分感知事物与以一个感知对象穷尽根本。"},{text:"知形形之不形乎！道不当名。",tone:"名与形",guide:"使形态发生的根本，不是某个同样固定的形态；道也不与一个名称完全相当。不当名不必改成绝不能使用道字，因为原文正持续使用这个名称。名称可以指引，却不能完成全部界定。"},{text:"道无问，问无应……外不观乎宇宙，内不知乎大初。",tone:"问答",guide:"问者期待确定对象与确定答案，应者强作回应，可能共同困在预设之中。原文确实严厉批评这类问答，不应抹去其力度；但结尾仍以观宇宙、知大初为通达方向，不能一概整理成停止观察和停止一切提问。"}]}),n[29]||(n[29]=i("",10)),a(s,{sections:P,glossary:v,"default-mode":"classic","aria-label":"知北游·光曜问无有 原文"}),n[30]||(n[30]=t("h3",{id:"生僻字词-8",tabindex:"-1"},[e("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词-8","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(r,{items:[{term:"光曜",pinyin:["guāng","yào"],meaning:"寓言人物名，关联光明、明照。"},{term:"无有",pinyin:["wú","yǒu"],meaning:"寓言人物名，参与对有无的反省。"},{term:"孰视",pinyin:["shú","shì"],meaning:"仔细看，孰联系熟理解。"},{term:"窨然",pinyin:["yìn","rán"],meaning:"幽深的样子，读音宜依底本统一。"},{term:"搏",pinyin:["bó"],meaning:"抓取、执取。"},{term:"有无",pinyin:["yǒu","wú"],meaning:"以无为所知、所持，或知有无等，有解释空间。"},{term:"无无",pinyin:["wú","wú"],meaning:"连所执的无也不再据有。"}]}),n[31]||(n[31]=t("h3",{id:"核心句引读-8",tabindex:"-1"},[e("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读-8","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(d,{title:"放下有之后，仍可能把无变成一个新的所有物",subtitle:"无无反省对无的据执，不是制造更高等级的称号。",lines:[{text:"夫子有乎？其无有乎？",tone:"两分",guide:"光曜以有或无有发问，期待将对方放进二分。无有未给出可取得的回答，故事让这套问法遇到限度。但原文没有交代无有故意沉默的心理，不能补成他预先判断所有问句都不对。"},{text:"终日视之而不见，听之而不闻，搏之而不得也。",tone:"执取",guide:"看、听、抓取都未取得对象，承接前段对闻见言的限制。这是寓言中对对象化执取的反省，不必宣称一切真实都应当不可见，更不能把不可观察本身当作某种主张正确的证据。"},{text:"予能有无矣，而未能无无也。",tone:"无无",guide:"即使能够否定有、谈论无，仍可能把无当成一种所得、一项境界或自我凭据。无无可理解为继续松开这一据执。不需要据此建立普通人、有无者、无无者的严格三层体系，也不必无限添加否定才算更高。"},{text:"及为无有矣，何从至此哉！",tone:"未尽",guide:"结尾仍保留怎样到达的感叹，没有给出操作步骤。不能直接把这个未解问题变成全篇已经完成的最终答案。本段让读者看见：连我已经放下的自我确认，也可能重新成为所执。"}]}),n[32]||(n[32]=i("",32)),a(s,{sections:T,glossary:S,"default-mode":"classic","aria-label":"知北游·捶钩者有守 原文"}),n[33]||(n[33]=t("h3",{id:"生僻字词-9",tabindex:"-1"},[e("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词-9","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(r,{items:[{term:"大马",pinyin:["dà","mǎ"],meaning:"传统常联系大司马这一官名理解。"},{term:"捶钩",pinyin:["chuí","gōu"],meaning:"锻打带钩等器物。"},{term:"豪芒",pinyin:["háo","máng"],meaning:"毫芒之细，豪通毫。"},{term:"守",pinyin:["shǒu"],meaning:"守持，本文以长期专注说明。"},{term:"假",pinyin:["jiǎ"],meaning:"借助。"},{term:"斫",pinyin:["zhuó"],meaning:"砍削。轮扁斫轮见《天道》。"}]}),n[34]||(n[34]=t("h3",{id:"核心句引读-9",tabindex:"-1"},[e("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读-9","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(d,{title:"不分散的注意，成就长期精细的技艺",subtitle:"不用不是无用，专注也不是停止学习。",lines:[{text:"年八十矣，而不失豪芒。",tone:"精细",guide:"故事突出工匠年高而制作仍精细。不是说身体完全没有衰老，也不保证只要专注就能免除所有年龄影响。大马从实际成果追问巧与道，使全篇重新落到可见的制作活动中。"},{text:"臣有守也。臣之年二十而好捶钩。",tone:"长期",guide:"工匠没有以神秘能力作答，而是说明从二十岁开始喜好、守持此事。年八十与年二十相对，突出长期积累。不能只留下放下知识，而抹去训练、经验和时间在技艺中的作用。"},{text:"于物无视也，非钩无察也。",tone:"专注",guide:"不把注意分散到其他事物，专察所作之钩，是故事中的专一表达。它不应变成现实工匠可以忽略安全、健康和他人权益的规则，也不要求每个人一生只能学习一种事。重点在减少与当前制作无关的分心。"},{text:"是用之者，假不用者也。",tone:"用与不用",guide:"此处之用借助不用于他事的心力。不用是注意资源的安排，不完全等于《人间世》中不被取用的无用。可以相互启发，却不能把两个不同语境合成同一概念。"},{text:"又有轮扁斫轮之说，此类是也。",tone:"对读",guide:"原文明确提及轮扁故事，说明此类技艺的理解不止于抽象说法。《天道》的轮扁还涉及实践分寸难以充分传授，并非只讲专注。言说不能尽技艺，不等于经验与说明都无价值。"}]}),n[35]||(n[35]=i("",11)),a(s,{sections:A,glossary:C,"default-mode":"classic","aria-label":"知北游·冉求问仲尼 原文"}),n[36]||(n[36]=t("blockquote",null,[t("p",null,[t("strong",null,"阅读说明："),e("「不以生生死」「物不得先物」「非物无止，非止无道」均有训释空间。本页不将这些句子强定为一套完整、无争议的宇宙生成公式。")])],-1)),n[37]||(n[37]=t("h3",{id:"生僻字词-10",tabindex:"-1"},[e("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词-10","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(r,{items:[{term:"冉求",pinyin:["rǎn","qiú"],meaning:"孔子弟子，字子有。"},{term:"昭然",pinyin:["zhāo","rán"],meaning:"清楚明白的样子。"},{term:"昧然",pinyin:["mèi","rán"],meaning:"昏昧不明的样子。"},{term:"神者先受之",pinyin:["shén","zhě","xiān","shòu","zhī"],meaning:"精神先有所领受、相契等。"},{term:"物物者",pinyin:["wù","wù","zhě"],meaning:"使事物成为事物的根本。"},{term:"止",pinyin:["zhǐ"],meaning:"止处、定止或界限等，末句解释有争议。"},{term:"道无以名",pinyin:["dào","wú","yǐ","míng"],meaning:"名称不足以充分确定道。"}]}),n[38]||(n[38]=t("h3",{id:"核心句引读-10",tabindex:"-1"},[e("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读-10","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(d,{title:"生成的根本，不能直接当成时间中更早的一件物",subtitle:"领会与分析的张力，不等于直觉必然正确。",lines:[{text:"未有天地可知乎？……可。古犹今也。",tone:"古今",guide:"冉求追问天地未有之前，孔子却由古犹今回应，使问题从遥远过去转向根本是否因古今而异。不能把这句直接当作现代宇宙学关于宇宙诞生前的知识主张，也不必认定过去与现在所有事实相同。"},{text:"昔之昭然也，神者先受之；今之昧然也，且又为不神之累也。",tone:"领受",guide:"先有所相契，后来又受某种固执、非通达的理解所累，是可把握的对比。神不神不能直接套成现代直觉与推理的二分。分析可能澄清也可能使人固执，直觉可能启发也可能误导，本段不是保证第一感受永远正确。"},{text:"无古无今，无始无终。未有子孙而有子孙，可乎？",tone:"反问",guide:"古今终始的固定分别受到反省，子孙之问又把生成关系摆在面前。原文是反问，不是明确肯定尚未出生的子孙与已出生者同时存在。较稳妥的是检验：能否用已经生成的某物解释一切生成，而不陷入同样的问题。"},{text:"不以生生死，不以死死生。",tone:"生死",guide:"句中名词、动词交叠，解释有争议。可联系不以生或死的一端作为另一端的全部根据，继续追问二者所依。不能只重复不用生来生死而不作辨析，也不宜据此取消生死在经验中的差异。"},{text:"有先天地生者物邪？物物者非物。",tone:"非物",guide:"若追问天地之前的根本，不能立即把它设成另一件已经生成的物。使物成为物者不与具体物同类，这是本段最清楚的区分。它不是把道排到时间轴最前端，作为宇宙中的第一件物。"},{text:"非物无止，非止无道，道无以名。",tone:"疑难",guide:"非与止的用法有不同解释，不宜单凭字面建立道没有限制、但又必须依限制存在的确定公式。可先保留与物物者非物相接的方向：根本不能由某一物、某一止处或某一名称穷尽。具体训释应依所用注本校定。"}]}),n[39]||(n[39]=i("",10)),a(s,{sections:j,glossary:V,"default-mode":"classic","aria-label":"知北游·颜渊问其游 原文"}),n[40]||(n[40]=t("blockquote",null,[t("p",null,[t("strong",null,"阅读说明："),e("「安化安不化」「安与之相靡，必与之莫多」有句读和训释问题。本页不将所有「安」都强定为安然顺受，也不将「物亦不能伤」作为现实免伤规律。")])],-1)),n[41]||(n[41]=t("h3",{id:"生僻字词-11",tabindex:"-1"},[e("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词-11","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(r,{items:[{term:"将",pinyin:["jiāng"],meaning:"此处常联系送理解。"},{term:"相靡",pinyin:["xiāng","mǐ"],meaning:"相随、相摩等，有不同训释。"},{term:"囿",pinyin:["yòu"],meaning:"苑囿。"},{term:"圃",pinyin:["pǔ"],meaning:"园圃。"},{term:"赀",pinyin:["zī"],meaning:"相计、相较或相诋等。"},{term:"皋壤",pinyin:["gāo","rǎng"],meaning:"水边高地、岸边土地等。"},{term:"御",pinyin:["yù"],meaning:"抵御、阻止。"},{term:"逆旅",pinyin:["nì","lǚ"],meaning:"旅舍、客栈。"},{term:"务",pinyin:["wù"],meaning:"力求、致力。"},{term:"齐知之所知",pinyin:["qí","zhī","zhī","suǒ","zhī"],meaning:"限于现有认识所能知，具体训释宜依注本。"}]}),n[42]||(n[42]=t("h3",{id:"核心句引读-11",tabindex:"-1"},[e("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读-11","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(d,{title:"随变化而应，不让外物夺其根本；承认有限，却不取消行动",subtitle:"篇末既说不伤，也明确写出哀乐来去与人的不能。",lines:[{text:"无有所将，无有所迎。",tone:"来往",guide:"可以联系不预先追送、不刻意迎取，不以自我执持规定来往。后文却说为能与人相将迎，说明不是永远关闭人际关系。少一点对往来的强求，与更真实地相处，可以并行。"},{text:"古之人，外化而内不化；今之人，内化而外不化。",tone:"内外",guide:"外在能随情势改变，内在不被得失夺其根本，与内心被牵引、外形却固守不变形成对比。不能把不化立即定为一个永恒实体，也不能用古今对举断言所有古人通达、所有今人失败。它首先突出两种处身方式。"},{text:"与物化者，一不化者也。安化安不化……",tone:"化与不化",guide:"随物变化与不失根本如何相接，是这组句子的焦点。一、安、相靡、莫多都有解释空间。安还可能具有何、焉的疑问用法，不宜全译成顺安。即使联系道理解不化，也不能省去句子自身的疑难，直接宣布道是完全静止的实体。"},{text:"圣人处物不伤物。不伤物者，物亦不能伤也。",tone:"不伤",guide:"原文理想化地写不侵伤的相处及其回应，可以联系不强作、不争夺来理解。但现实中不伤人者仍可能受害，不能从受伤倒推其必定先伤物。自我修养不替代防护、求助和对施害者责任的判断。"},{text:"哀乐之来，吾不能御，其去弗能止。",tone:"哀乐",guide:"篇末没有把通达写成彻底没有情绪，反而明确承认哀乐来去不能全控。情绪发生不等于修养失败。能减少强留、强拒，与承认真实感受并行；这也不意味着情绪完全不能调节或无需支持。"},{text:"世人直为物逆旅耳！",tone:"逆旅",guide:"以旅馆写外物与哀乐来去，不必把每次出现都据为恒久的我。但人不是毫无回应能力的空房：前文仍强调应物与相将迎，后文又辨知识能力的限度。暂住的譬喻提醒不固藏，不取消行动。"},{text:"无知无能者，固人之所不免也。",tone:"有限",guide:"人总有未知与不能，不可能靠强求消除全部限度。不能把句子改成学习没用、困难无法改善。捶钩者恰以长期实践成就其用；应区别改善具体能力与要求自己无所不知、无所不能。"},{text:"至言去言，至为去为，齐知之所知，则浅矣。",tone:"收束",guide:"至言与至为解除对言、为的固执与造作，不是最终要求永不说话、永不做事。知的边界不应被当成世界的边界；承认这一点，也不必抛弃已有认识。全篇以言展开、以实践作证，最后限制的是把言、为、知据为终极。"}]}),n[43]||(n[43]=i("",121))])}}});export{B as __pageData,H as default};
